var i=[{slug:"reklama-swiadczen-zdrowotnych-co-wolno",title:"Reklama \u015Bwiadcze\u0144 zdrowotnych: co wolno",h1:"Reklama \u015Bwiadcze\u0144 zdrowotnych: gdzie ko\u0144czy si\u0119 informacja, a zaczyna wykroczenie",seoTitle:"Reklama us\u0142ug medycznych: co wolno, a za co grozi kara (art. 14) | mediaso",seoDescription:"Lista dozwolonych i zakazanych tre\u015Bci dla plac\xF3wek i lekarzy: ceny, promocje, zdj\u0119cia przed i po, social media. Art. 14, art. 147a k.w. i Kodeks Etyki Lekarskiej 2025.",datePublished:"2026-09-22",dateModified:"2026-10-25",readingMinutes:9,motif:"pulse",image:{src:"/blog/reklama-swiadczen-stetoskop.jpg",alt:"Stetoskop zawieszony na \u015Bcianie gabinetu, zdj\u0119cie czarno-bia\u0142e",width:1280,height:853,credit:"Pixabay, Content License",creditUrl:"https://pixabay.com/photos/stethoscope-hospital-doctor-health-840125/"},lead:'Plac\xF3wka medyczna mo\u017Ce informowa\u0107 o tym, co robi, ale nie mo\u017Ce zach\u0119ca\u0107 do skorzystania. Ta jedna r\xF3\u017Cnica stoi za art. 14 ustawy o dzia\u0142alno\u015Bci leczniczej i za art. 147a Kodeksu wykrocze\u0144, kt\xF3ry za podanie do publicznej wiadomo\u015Bci informacji o \u015Bwiadczeniach w formie reklamy przewiduje grzywn\u0119, ograniczenie wolno\u015Bci albo areszt. Przepis brzmi szeroko i st\u0105d bierze si\u0119 wi\u0119kszo\u015B\u0107 w\u0105tpliwo\u015Bci: ten sam post na Facebooku raz jest legaln\u0105 informacj\u0105 o uruchomieniu pracowni USG, a raz reklam\u0105, bo dopisano do niego \u201Epromocja do ko\u0144ca miesi\u0105ca". Od 1 stycznia 2025 roku dosz\u0142a druga warstwa: nowy Kodeks Etyki Lekarskiej, kt\xF3ry usun\u0105\u0142 zdanie o zakazie reklamowania si\u0119 i zast\u0105pi\u0142 je zasadami informowania. Trzecia warstwa to ustawa o wyrobach medycznych, gdzie kary si\u0119gaj\u0105 milion\xF3w z\u0142otych i nak\u0142ada je Prezes UOKiK. Poni\u017Cej trzy warstwy w jednej li\u015Bcie: co wolno napisa\u0107, czego nie i jak sprawdzi\u0107 materia\u0142 przed publikacj\u0105.',sections:[{heading:"Jedno zdanie ustawy, na kt\xF3rym opiera si\u0119 ca\u0142a reszta",paragraphs:["Art. 14 ust. 1 ustawy o dzia\u0142alno\u015Bci leczniczej pozwala podmiotowi wykonuj\u0105cemu dzia\u0142alno\u015B\u0107 lecznicz\u0105 podawa\u0107 do wiadomo\u015Bci publicznej informacje o zakresie i rodzajach udzielanych \u015Bwiadcze\u0144 zdrowotnych, pod warunkiem \u017Ce tre\u015B\u0107 i forma tych informacji nie maj\u0105 cech reklamy. Ustawa nie m\xF3wi, czym s\u0105 cechy reklamy. T\u0119 granic\u0119 wyznaczy\u0142y orzecznictwo i stanowiska Naczelnej Izby Lekarskiej.","Informacja to przekaz rzeczowy i neutralny: jakie \u015Bwiadczenia plac\xF3wka wykonuje, kto je wykonuje, gdzie i w jakich godzinach. Reklama to ten sam przekaz plus zach\u0119ta do skorzystania, nastawiona na wzrost liczby pacjent\xF3w i przychodu. O ocenie decyduje warstwa j\u0119zykowa. Zdanie o uruchomieniu pracowni endoskopii jest legalne jako komunikat oznajmuj\u0105cy i staje si\u0119 wykroczeniem po dopisaniu has\u0142a o promocyjnej cenie pierwszych dwudziestu bada\u0144."],bullets:["informacja opisuje stan faktyczny: zakres \u015Bwiadcze\u0144, miejsce, godziny, kwalifikacje personelu","reklama dok\u0142ada zach\u0119t\u0119: rabat, ograniczenie czasowe, warto\u015Bciowanie, obietnic\u0119 efektu","kana\u0142 nie zmienia oceny: ulotka, strona, Google Ads i Instagram podlegaj\u0105 tej samej zasadzie","zakaz wi\u0105\u017Ce podmiot leczniczy i praktyk\u0119 zawodow\u0105, nie sklep z suplementami czy gabinet kosmetyczny"],note:"Art. 147a \xA7 2 Kodeksu wykrocze\u0144: kto podaje do wiadomo\u015Bci publicznej informacje o zakresie i rodzajach udzielanych \u015Bwiadcze\u0144 zdrowotnych maj\u0105ce form\u0119 i tre\u015B\u0107 reklamy, podlega karze aresztu, ograniczenia wolno\u015Bci albo grzywny."},{heading:"Co wolno napisa\u0107 bez ryzyka",paragraphs:['Lista bezpiecznych tre\u015Bci jest d\u0142u\u017Csza, ni\u017C wynika to z obiegowej opinii, \u017Ce \u201Ew medycynie nic nie wolno". Wolno opisa\u0107 ca\u0142\u0105 operacyjn\u0105 stron\u0119 plac\xF3wki: kto przyjmuje, z czym, kiedy i jak si\u0119 zapisa\u0107. Wolno poda\u0107 wykszta\u0142cenie, specjalizacje, sta\u017C i przynale\u017Cno\u015B\u0107 do towarzystw naukowych, o ile dane s\u0105 prawdziwe i sprawdzalne. Wolno nazwa\u0107 sprz\u0119t i metod\u0119, kt\xF3r\u0105 plac\xF3wka pracuje, pod warunkiem \u017Ce opis pozostaje techniczny, a nie perswazyjny.',"Pacjent szukaj\u0105cy ortopedy potrzebuje dok\u0142adnie tych informacji, wi\u0119c rzetelny opis us\u0142ug jest jednocze\u015Bnie zgodny z prawem i lepszy sprzeda\u017Cowo ni\u017C has\u0142o reklamowe. Strona, kt\xF3ra odpowiada na pytania o skierowanie, czas trwania wizyty, przygotowanie do badania i spos\xF3b odbioru wynik\xF3w, przynosi wi\u0119cej rejestracji ni\u017C nag\u0142\xF3wek o najnowocze\u015Bniejszym sprz\u0119cie w wojew\xF3dztwie."],bullets:["nazwa, adres, dojazd, parking, dost\u0119pno\u015B\u0107 dla os\xF3b z niepe\u0142nosprawno\u015Bciami","zakres \u015Bwiadcze\u0144 nazwany j\u0119zykiem pacjenta, bez warto\u015Bciowania","imiona, nazwiska, tytu\u0142y i specjalizacje os\xF3b udzielaj\u0105cych \u015Bwiadcze\u0144","godziny pracy rejestracji i poszczeg\xF3lnych poradni","telefon, adres rejestracji online, zasady odwo\u0142ywania wizyt","nazwa i parametry sprz\u0119tu opisane rzeczowo","wysoko\u015B\u0107 op\u0142at wynikaj\u0105ca z regulaminu organizacyjnego"],image:{src:"/blog/reklama-swiadczen-wejscie.jpg",alt:"Drzwi do korytarza plac\xF3wki medycznej z klamk\u0105 antypaniczn\u0105",width:1280,height:853,credit:"Pixabay, Content License",creditUrl:"https://pixabay.com/photos/door-entry-hospital-passage-red-349807/"}},{heading:"Ceny i promocje: najcz\u0119stszy b\u0142\u0105d plac\xF3wek",paragraphs:["Podanie cen bywa obowi\u0105zkiem. Regulamin organizacyjny podmiotu leczniczego okre\u015Bla wysoko\u015B\u0107 op\u0142at za \u015Bwiadczenia udzielane odp\u0142atnie, a informacj\u0119 o nich plac\xF3wka podaje do wiadomo\u015Bci pacjent\xF3w. Cennik na stronie i w rejestracji jest wi\u0119c wykonaniem obowi\u0105zku informacyjnego, nie reklam\u0105.","Reklam\u0105 staje si\u0119 dopiero operowanie cen\u0105: rabat, kod zni\u017Ckowy, pakiet w cenie ni\u017Cszej ni\u017C suma pozycji, por\xF3wnanie do ceny wcze\u015Bniejszej, termin wa\u017Cno\u015Bci oferty. Ta sama logika obejmuje serwisy zakup\xF3w grupowych, bo zabieg wystawiony jako okazja dnia jest zach\u0119t\u0105 w czystej postaci. Je\u015Bli plac\xF3wka zmienia cennik, publikuje nowy cennik, a nie komunikat o obni\u017Cce."],bullets:["cennik jako tabela pozycji i kwot: dopuszczalny i potrzebny",'kwota przekre\u015Blona, \u201E-30%", \u201Epakiet \u015Bwi\u0105teczny", \u201Edo ko\u0144ca miesi\u0105ca": zach\u0119ta',"zabiegi na platformach zakup\xF3w grupowych: reklama niezale\u017Cnie od sformu\u0142owania","bezp\u0142atna konsultacja przed zabiegiem komercyjnym: traktowana jak zach\u0119ta"]},{heading:"Kodeks Etyki Lekarskiej po 1 stycznia 2025 roku",paragraphs:['Poprzedni Kodeks Etyki Lekarskiej zawiera\u0142 zdanie, \u017Ce wszelkie reklamowanie si\u0119 jest zabronione. Taki zapis okaza\u0142 si\u0119 nie do pogodzenia z prawem unijnym i znikn\u0105\u0142. Obowi\u0105zuj\u0105cy od 1 stycznia 2025 roku art. 71 nowego kodeksu nie pos\u0142uguje si\u0119 ju\u017C s\u0142owem \u201Ereklama": m\xF3wi o informowaniu o dzia\u0142alno\u015Bci zawodowej, kt\xF3re ma pozosta\u0107 zgodne z zasadami etyki lekarskiej. Informacj\u0105 jest przy tym ka\u017Cda forma przekazu upowszechniaj\u0105cego wizerunek lekarza lub jego us\u0142ugi.',"Zmiana poszerza pole manewru, ale nie znosi granic. Lekarzowi nadal nie wolno deprecjonowa\u0107 innych lekarzy, przedstawia\u0107 si\u0119 jako jedyny czy najlepszy, ani wykorzystywa\u0107 autorytetu zawodu do promowania rzeczy z nim niezwi\u0105zanych, od suplement\xF3w po kosmetyki. Odpowiedzialno\u015B\u0107 biegnie przed rzecznikiem odpowiedzialno\u015Bci zawodowej i s\u0105dem lekarskim, niezale\u017Cnie od odpowiedzialno\u015Bci podmiotu leczniczego za tre\u015Bci wydane pod jego szyldem."],note:"Zmiana w kodeksie etyki nie uchyli\u0142a art. 14 ustawy o dzia\u0142alno\u015Bci leczniczej. Lekarz jako osoba ma dzi\u015B szersze pole ni\u017C przychodnia jako podmiot i to podmiot odpowiada za tre\u015Bci na stronie i w kampaniach."},{heading:"Wyroby medyczne to osobne przepisy i zupe\u0142nie inne kary",paragraphs:["Ustawa o wyrobach medycznych z 2022 roku wprowadzi\u0142a od 1 stycznia 2023 roku w\u0142asny re\u017Cim reklamowy, kt\xF3ry dzia\u0142a r\xF3wnolegle do ustawy o dzia\u0142alno\u015Bci leczniczej. Reklama wyrobu kierowana do publicznej wiadomo\u015Bci nie mo\u017Ce wykorzystywa\u0107 wizerunku os\xF3b wykonuj\u0105cych zawody medyczne ani os\xF3b podaj\u0105cych si\u0119 za takie osoby, ani przedstawia\u0107 prezentuj\u0105cego w spos\xF3b sugeruj\u0105cy wykonywanie takiego zawodu. Fartuch, stetoskop i wn\u0119trze gabinetu w kadrze wystarcz\u0105, \u017Ceby przepis zadzia\u0142a\u0142.","Dotyczy to materia\u0142\xF3w, kt\xF3re plac\xF3wki publikuj\u0105 rutynowo: aparatu do lasera frakcyjnego, implant\xF3w, soczewek, aparat\xF3w s\u0142uchowych, skaner\xF3w wewn\u0105trzustnych. Sankcje nak\u0142ada Prezes UOKiK i Prezes Urz\u0119du Rejestracji: do 2 milion\xF3w z\u0142otych za reklam\u0119 niezgodn\u0105 z przepisami i do 5 milion\xF3w za reklam\u0119 wprowadzaj\u0105c\u0105 w b\u0142\u0105d. Wsp\xF3\u0142praca z producentem sprz\u0119tu wymaga wi\u0119c sprawdzenia, kto formalnie jest nadawc\u0105 materia\u0142u."]},{heading:"Jak to wygl\u0105da w kana\u0142ach, kt\xF3rych plac\xF3wki u\u017Cywaj\u0105 codziennie",paragraphs:['Na stronie internetowej ryzyko siedzi najcz\u0119\u015Bciej w nag\u0142\xF3wkach i sekcji \u201Edlaczego my". Opisy us\u0142ug zwykle s\u0105 poprawne, bo powstaj\u0105 na bazie dokumentacji. Wywraca je zdanie o najlepszym zespole w mie\u015Bcie albo licznik zadowolonych pacjent\xF3w. Usuni\u0119cie superlatyw\xF3w z trzech ekran\xF3w strony rozwi\u0105zuje zwykle wi\u0119kszo\u015B\u0107 problemu.',"W Google Ads sama obecno\u015B\u0107 plac\xF3wki nie jest zakazana i stanowiska prawnik\xF3w s\u0105 tu podzielone, natomiast teksty reklam podlegaj\u0105 art. 14 tak samo jak ulotka. Bezpieczna kampania kieruje na zapytania o konkretn\u0105 us\u0142ug\u0119 i m\xF3wi, co plac\xF3wka robi, gdzie i kiedy przyjmuje. Do tego dochodz\u0105 polityki Google i Meta dotycz\u0105ce zdrowia, kt\xF3re bywaj\u0105 ostrzejsze ni\u017C polskie prawo i odrzuc\u0105 kreacj\u0119.","W mediach spo\u0142eczno\u015Bciowych granic\u0119 przekracza si\u0119 najszybciej, bo format popycha do zach\u0119ty. Relacja z konferencji, wyja\u015Bnienie procedury, przedstawienie nowego specjalisty i komunikat organizacyjny mieszcz\u0105 si\u0119 w informacji. Konkurs z zabiegiem w nagrod\u0119, wsp\xF3\u0142praca z influencerem opisuj\u0105cym zabieg jak produkt i zdj\u0119cia przed i po u\u017Cywane jako dow\xF3d skuteczno\u015Bci to obszar, w kt\xF3rym izby lekarskie prowadz\u0105 post\u0119powania."],image:{src:"/blog/reklama-swiadczen-teleporada.jpg",alt:"Laptop na drewnianym biurku z lekarzem trzymaj\u0105cym stetoskop na ekranie",width:1280,height:705,credit:"Pixabay, Content License",creditUrl:"https://pixabay.com/photos/doctor-telemedicine-laptop-6161898/"},link:{path:"/wiedza/czym-jest-marketing-medyczny",label:"Czym jest marketing medyczny",description:"Pe\u0142na lista kana\u0142\xF3w i tego, co w ka\u017Cdym z nich wolno pokaza\u0107."}},{heading:"Czerwone flagi, po kt\xF3rych poznasz reklam\u0119 we w\u0142asnym tek\u015Bcie",paragraphs:["Przy ocenie materia\u0142u pomaga proste \u0107wiczenie: wykre\u015Bl z tekstu ka\u017Cde zdanie, kt\xF3rego nie da si\u0119 zweryfikowa\u0107 dokumentem, zdj\u0119ciem albo wpisem w rejestrze. To, co zostanie, jest informacj\u0105. To, co wykre\u015Bli\u0142e\u015B, by\u0142o najcz\u0119\u015Bciej zach\u0119t\u0105."],bullets:["superlatywy i por\xF3wnania: najlepszy, najnowocze\u015Bniejszy, najta\u0144szy, lider w regionie","obietnica albo gwarancja efektu leczenia","rabaty, kody, pakiety, konkursy i nagrody w postaci \u015Bwiadcze\u0144","zdj\u0119cia przed i po prezentowane jako dow\xF3d skuteczno\u015Bci","opinie pacjent\xF3w pozyskane w zamian za rabat lub upominek","influencer relacjonuj\u0105cy zabieg w konwencji recenzji produktu","wizerunek osoby w fartuchu w materiale promuj\u0105cym wyr\xF3b medyczny"],note:"Opinie zbierane za korzy\u015B\u0107 \u0142ami\u0105 jednocze\u015Bnie wytyczne Google i przepisy o nieuczciwych praktykach rynkowych. Spos\xF3b na zbieranie ich legalnie opisali\u015Bmy osobno."},{heading:"Proces akceptacji tre\u015Bci zamiast sprawdzania ka\u017Cdego posta osobno",paragraphs:["Plac\xF3wki wpadaj\u0105 w k\u0142opoty nie dlatego, \u017Ce nie znaj\u0105 przepisu, tylko dlatego, \u017Ce posta publikuje o 22:00 osoba, kt\xF3ra nigdy o tym przepisie nie s\u0142ysza\u0142a. Dzia\u0142a proces akceptacji tre\u015Bci. Jedna osoba w plac\xF3wce akceptuje tre\u015Bci przed publikacj\u0105 i zadaje trzy pytania: czy zdanie opisuje fakt, czy fakt da si\u0119 udowodni\u0107, czy tekst zawiera zach\u0119t\u0119, rabat lub warto\u015Bciowanie.","Do tego wystarczy archiwum: zrzut ka\u017Cdej publikacji z dat\u0105, w jednym folderze. Je\u015Bli izba albo konkurencja zg\u0142osi spraw\u0119 po roku, materia\u0142 dowodowy jest pod r\u0119k\u0105. W umowie z agencj\u0105 marketingow\u0105 warto zapisa\u0107 wprost, kto odpowiada za zgodno\u015B\u0107 tre\u015Bci z art. 14 i kto akceptuje kreacje przed emisj\u0105."],bullets:['jedna osoba akceptuj\u0105ca tre\u015Bci, wskazana z imienia, nie \u201Ezesp\xF3\u0142"',"trzy pytania kontrolne przed publikacj\u0105","archiwum zrzut\xF3w wszystkich publikacji i kreacji reklamowych","zapis w umowie z agencj\u0105 o odpowiedzialno\u015Bci za zgodno\u015B\u0107 tre\u015Bci","przegl\u0105d strony raz na kwarta\u0142 pod k\u0105tem superlatyw\xF3w"],image:{src:"/blog/reklama-swiadczen-schody.jpg",alt:"Klatka schodowa w budynku szpitala z pomara\u0144czowymi stopniami",width:853,height:1280,credit:"Pixabay, Content License",creditUrl:"https://pixabay.com/photos/stairs-corridor-hospital-orange-2105208/"}},{heading:"Kto to egzekwuje i od czego zwykle si\u0119 zaczyna",paragraphs:["Sprawy rzadko wychodz\u0105 od urz\u0119du. Najcz\u0119\u015Bciej zg\u0142asza je konkurencyjna plac\xF3wka z tej samej dzielnicy, czasem pacjent, czasem izba po tym, jak materia\u0142 zrobi\u0142 zasi\u0119gi. Dalej post\u0119powanie idzie dwiema drogami: zawodow\u0105, przed rzecznikiem odpowiedzialno\u015Bci zawodowej i s\u0105dem lekarskim, oraz wykroczeniow\u0105, na podstawie art. 147a Kodeksu wykrocze\u0144. Przy wyrobach medycznych dochodzi droga administracyjna z karami pieni\u0119\u017Cnymi.","Ryzyko ro\u015Bnie razem z zasi\u0119giem. Materia\u0142, kt\xF3ry dobrze si\u0119 niesie, pr\u0119dzej trafi przed oczy kogo\u015B, kto go zg\u0142osi. Dlatego tre\u015Bci przeznaczone do promocji p\u0142atnej warto sprawdza\u0107 uwa\u017Cniej ni\u017C wpis widoczny dla stu os\xF3b."],note:"Ten tekst opisuje stan przepis\xF3w na wrzesie\u0144 2026 roku i nie jest porad\u0105 prawn\u0105. Przy w\u0105tpliwej kreacji taniej wychodzi godzina konsultacji z prawnikiem medycznym ni\u017C post\u0119powanie przed s\u0105dem lekarskim."}],faq:[{question:"Czy plac\xF3wka medyczna mo\u017Ce prowadzi\u0107 kampanie Google Ads?",answer:"Sama obecno\u015B\u0107 w p\u0142atnych wynikach nie jest zakazana, natomiast tre\u015B\u0107 reklamy podlega art. 14 ustawy o dzia\u0142alno\u015Bci leczniczej tak samo jak ulotka czy baner. Bezpieczna kampania informuje o zakresie \u015Bwiadcze\u0144, lokalizacji i godzinach przyj\u0119\u0107, bez rabat\xF3w, superlatyw\xF3w i obietnic efektu. Stanowiska prawnik\xF3w co do samej dopuszczalno\u015Bci kampanii s\u0105 podzielone, wi\u0119c kreacje warto skonsultowa\u0107."},{question:"Czy wolno podawa\u0107 ceny zabieg\xF3w na stronie?",answer:"Tak. Wysoko\u015B\u0107 op\u0142at za \u015Bwiadczenia udzielane odp\u0142atnie wynika z regulaminu organizacyjnego podmiotu leczniczego i podaje si\u0119 j\u0105 do wiadomo\u015Bci pacjent\xF3w. Reklam\u0105 staje si\u0119 dopiero operowanie cen\u0105: rabaty, kwoty przekre\u015Blone, pakiety promocyjne i oferty ograniczone terminem."},{question:"Czy zdj\u0119cia przed i po s\u0105 dozwolone?",answer:"Prezentowane jako dow\xF3d skuteczno\u015Bci i zach\u0119ta do zabiegu s\u0105 traktowane jako reklama, a dodatkowo pokazuj\u0105 dane o zdrowiu konkretnej osoby, co wymaga odr\u0119bnej zgody. W materia\u0142ach edukacyjnych i naukowych, kierowanych do profesjonalist\xF3w, ocena bywa inna. W komunikacji do pacjent\xF3w to jedno z najcz\u0119\u015Bciej kwestionowanych narz\u0119dzi."},{question:"Czy nowy Kodeks Etyki Lekarskiej zni\xF3s\u0142 zakaz reklamy?",answer:'Nie zni\xF3s\u0142 granic, tylko zmieni\u0142 j\u0119zyk. Od 1 stycznia 2025 roku kodeks nie pos\u0142uguje si\u0119 s\u0142owem \u201Ereklama" i pozwala lekarzowi informowa\u0107 o dzia\u0142alno\u015Bci zawodowej zgodnie z zasadami etyki. Nadal zabronione jest deprecjonowanie innych lekarzy, przedstawianie si\u0119 jako najlepszy czy jedyny oraz wykorzystywanie autorytetu zawodu do promocji us\u0142ug i produkt\xF3w niezwi\u0105zanych z medycyn\u0105. Przepisy ustawy o dzia\u0142alno\u015Bci leczniczej obowi\u0105zuj\u0105 niezale\u017Cnie od kodeksu.'},{question:"Jaka kara grozi za reklam\u0119 \u015Bwiadcze\u0144 zdrowotnych?",answer:"Za podanie do wiadomo\u015Bci publicznej informacji o \u015Bwiadczeniach w formie reklamy Kodeks wykrocze\u0144 przewiduje kar\u0119 aresztu, ograniczenia wolno\u015Bci albo grzywny, a lekarzowi grozi dodatkowo odpowiedzialno\u015B\u0107 zawodowa. Przy reklamie wyrob\xF3w medycznych kary s\u0105 administracyjne i si\u0119gaj\u0105 2 milion\xF3w z\u0142otych, a przy reklamie wprowadzaj\u0105cej w b\u0142\u0105d 5 milion\xF3w z\u0142otych."}],sources:[{label:"Ustawa z dnia 15 kwietnia 2011 r. o dzia\u0142alno\u015Bci leczniczej",url:"https://eli.gov.pl/eli/DU/2011/654/ogl",publisher:"Dziennik Ustaw"},{label:"Informowanie o dzia\u0142alno\u015Bci leczniczej a jej reklama",url:"https://nil.org.pl/dla-lekarzy/praktyka-lekarska/4240-informowanie-o-dzialalnosci-leczniczej-a-jej-reklama",publisher:"Naczelna Izba Lekarska"},{label:"Kodeks Etyki Lekarskiej",url:"https://nil.org.pl/dla-lekarzy/prawo/kodeks-etyki-lekarskiej",publisher:"Naczelna Izba Lekarska"},{label:"Reklama wyrob\xF3w medycznych. Nowe przepisy od 1 stycznia 2023 r.",url:"https://nil.org.pl/aktualnosci/7005-reklama-wyrobow-medycznych-nowe-przepisy-od-1-stycznia-2023-r",publisher:"Naczelna Izba Lekarska"}],related:[{path:"/wiedza/rodo-w-marketingu-placowki-medycznej",label:"RODO w marketingu plac\xF3wki medycznej",description:"Druga warstwa ogranicze\u0144: dane pacjent\xF3w w zdj\u0119ciach, opiniach i remarketingu."},{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Pro\u015Bba o opini\u0119 bez korzy\u015Bci maj\u0105tkowej i bez \u0142amania wytycznych Google."},{path:"/uslugi/social-media-dla-klinik",label:"Social media dla klinik",description:"Prowadzimy profile plac\xF3wek z akceptacj\u0105 tre\u015Bci po stronie zgodno\u015Bci z art. 14."}]},{slug:"wizytowka-google-dla-przychodni",title:"Wizyt\xF3wka Google dla przychodni",h1:"Wizyt\xF3wka Google dla przychodni: jak j\u0105 ustawi\u0107, \u017Ceby pacjenci trafiali do Ciebie",seoTitle:"Wizyt\xF3wka Google dla przychodni: 7 krok\xF3w i b\u0142\u0119dy, kt\xF3re blokuj\u0105 mapy | mediaso",seoDescription:"Jak ustawi\u0107 Profil Firmy w Google dla przychodni i gabinetu: kategoria g\u0142\xF3wna, us\u0142ugi, godziny, zdj\u0119cia, posty. 7 krok\xF3w na jedno popo\u0142udnie, bez \u017Cadnych op\u0142at.",datePublished:"2026-09-11",dateModified:"2026-10-25",readingMinutes:8,image:{src:"/blog/wizytowka-google-telefon.jpg",alt:"Osoba z kaw\u0105 w d\u0142oni przegl\u0105da wyniki wyszukiwania na smartfonie",width:1600,height:1067,credit:"Wikimedia Commons, CC0",creditUrl:"https://commons.wikimedia.org/wiki/File:Hands-coffee-smartphone-technology_(23698591814).jpg"},lead:'Wizyt\xF3wka Google, czyli Profil Firmy w Google, to wpis przychodni widoczny w mapach i w bloku wynik\xF3w lokalnych nad zwyk\u0142ymi wynikami wyszukiwania. Pacjent, kt\xF3ry wpisuje \u201Eortopeda Pozna\u0144" albo \u201Eprzychodnia Wilda", widzi najpierw trzy plac\xF3wki z mapy, ich oceny, godziny i przycisk \u201EZadzwo\u0144". Wi\u0119kszo\u015B\u0107 z nich dzwoni do jednej z tej tr\xF3jki, nie przewijaj\u0105c dalej. O tym, kt\xF3ra plac\xF3wka trafi do tr\xF3jki, decyduj\u0105 trzy rzeczy: trafno\u015B\u0107 wpisu wzgl\u0119dem zapytania, odleg\u0142o\u015B\u0107 od pacjenta i rozpoznawalno\u015B\u0107 plac\xF3wki, na kt\xF3r\u0105 sk\u0142adaj\u0105 si\u0119 opinie i sp\xF3jne dane w sieci. Na odleg\u0142o\u015B\u0107 nie masz wp\u0142ywu. Na trafno\u015B\u0107 masz wp\u0142yw niemal ca\u0142kowity i to ona jest tematem tego poradnika: od weryfikacji profilu, przez wyb\xF3r kategorii i list\u0119 us\u0142ug, po zdj\u0119cia, posty i pytania pacjent\xF3w. Ca\u0142o\u015B\u0107 da si\u0119 wykona\u0107 samodzielnie w jedno popo\u0142udnie.',sections:[{heading:"Krok 1: przejmij i zweryfikuj profil",paragraphs:["Zanim za\u0142o\u017Cysz nowy profil, wyszukaj swoj\u0105 plac\xF3wk\u0119 w Mapach Google. Przychodnie dzia\u0142aj\u0105ce od kilku lat cz\u0119sto maj\u0105 ju\u017C wpis utworzony automatycznie albo przez by\u0142ego pracownika. Drugi profil pod tym samym adresem to duplikat, kt\xF3ry dzieli opinie i obni\u017Ca widoczno\u015B\u0107 obu wpis\xF3w.",'Je\u015Bli wpis istnieje, kliknij \u201EZarz\u0105dzaj tym profilem" i przejd\u017A weryfikacj\u0119. Google proponuje zwykle nagranie wideo pokazuj\u0105ce szyld, wej\u015Bcie i dokument z adresem, czasem telefon lub list z kodem. Dost\u0119p w\u0142a\u015Bciciela zak\u0142adaj na konto Google plac\xF3wki, nie na prywatn\u0105 skrzynk\u0119 osoby, kt\xF3ra akurat si\u0119 tym zajmuje. Pozosta\u0142ym osobom nadawaj rol\u0119 mened\u017Cera.'],bullets:["sprawd\u017A, czy plac\xF3wka nie ma ju\u017C wpisu lub duplikatu","weryfikacja na koncie firmowym, nie prywatnym","rola w\u0142a\u015Bciciela dla plac\xF3wki, rola mened\u017Cera dla agencji i pracownik\xF3w",'nazwa dok\u0142adnie taka jak na szyldzie, bez dopisk\xF3w w rodzaju \u201Enajlepszy dentysta"'],note:"Dopisywanie fraz do nazwy firmy \u0142amie wytyczne Google. Konkurencja mo\u017Ce to zg\u0142osi\u0107, a skutkiem bywa zawieszenie profilu."},{heading:"Krok 2: kategoria g\u0142\xF3wna decyduje, na co si\u0119 wy\u015Bwietlasz",paragraphs:['Kategoria g\u0142\xF3wna to najwa\u017Cniejsze pole w ca\u0142ym profilu. Google na jej podstawie ocenia, na jakie zapytania plac\xF3wka jest trafn\u0105 odpowiedzi\u0105. Wyb\xF3r \u201EPrzychodnia" jest poprawny, ale og\xF3lny: taki wpis przegra na zapytanie \u201Edermatolog" z gabinetem, kt\xF3ry ma kategori\u0119 \u201EDermatolog".',"Kategori\u0119 g\u0142\xF3wn\u0105 ustaw na us\u0142ug\u0119, kt\xF3ra przynosi plac\xF3wce najwi\u0119cej przychodu albo na kt\xF3rej najbardziej ci zale\u017Cy. Kategorie dodatkowe, do dziewi\u0119ciu, opisuj\u0105 pozosta\u0142e specjalizacje. Nie dodawaj kategorii, kt\xF3rych nie wykonujesz. Obni\u017Caj\u0105 trafno\u015B\u0107 zamiast j\u0105 podnosi\u0107, a pacjent, kt\xF3ry zadzwoni po us\u0142ug\u0119, kt\xF3rej nie ma, jest straconym po\u0142\u0105czeniem dla rejestracji."],bullets:['kategoria g\u0142\xF3wna: najwa\u017Cniejsza us\u0142uga, nie og\xF3lna \u201EPrzychodnia"',"kategorie dodatkowe tylko dla us\u0142ug realnie wykonywanych","raz na kwarta\u0142 sprawd\u017A kategorie trzech konkurent\xF3w z mapy"]},{heading:"Krok 3: us\u0142ugi, opis i atrybuty",paragraphs:['Sekcja us\u0142ug pozwala doda\u0107 ka\u017Cd\u0105 us\u0142ug\u0119 osobno, z kr\xF3tkim opisem i cen\u0105. Pacjent widzi j\u0105 w profilu, a Google czyta j\u0105 przy dopasowaniu zapyta\u0144. Wpisz us\u0142ugi j\u0119zykiem pacjenta: \u201Eusuwanie znamion", nie \u201Edermatochirurgia zmian barwnikowych". Je\u015Bli masz cennik na stronie, ceny w profilu musz\u0105 si\u0119 z nim zgadza\u0107.',"Opis plac\xF3wki ma 750 znak\xF3w. Pierwsze zdania wida\u0107 bez rozwijania, wi\u0119c zacznij od konkret\xF3w: jakie specjalizacje, dla kogo, w jakiej dzielnicy, czy jest NFZ, czy s\u0105 wizyty prywatne. Na ko\u0144cu dopisz atrybuty: dost\u0119p dla w\xF3zk\xF3w, parking, rejestracja online. Pacjent filtruje po nich wyniki cz\u0119\u015Bciej, ni\u017C si\u0119 wydaje."]},{heading:"Krok 4: godziny, telefon i link do rejestracji",paragraphs:["Godziny otwarcia wpisuj tak, jak faktycznie dzia\u0142a rejestracja, nie gabinet zabiegowy. Pacjent, kt\xF3ry dzwoni w godzinach z profilu i nikt nie odbiera, rzadko pr\xF3buje drugi raz. Przed ka\u017Cdym \u015Bwi\u0119tem ustaw godziny specjalne. Google o nie przypomina, a profil bez nich pokazuje w Wigili\u0119 zwyk\u0142y czwartek.","Numer telefonu musi by\u0107 ten sam co na stronie i w innych katalogach, na przyk\u0142ad w ZnanyLekarz. Rozbie\u017Cne numery w sieci os\u0142abiaj\u0105 rozpoznawalno\u015B\u0107 plac\xF3wki. W polu linku do wizyt podaj adres rejestracji online albo podstron\u0119 kontaktu. Link do strony g\u0142\xF3wnej ka\u017Ce pacjentowi szuka\u0107 przycisku jeszcze raz."],bullets:["godziny pracy rejestracji, nie gabinet\xF3w","godziny specjalne przed ka\u017Cdym \u015Bwi\u0119tem i urlopem","jeden numer telefonu wsz\u0119dzie: profil, strona, katalogi","link do umawiania wizyt prowadzi prosto do formularza lub systemu rejestracji"],image:{src:"/blog/wizytowka-google-poczekalnia.jpg",alt:"Rejestracja i poczekalnia przychodni z krzes\u0142ami dla pacjent\xF3w",width:1600,height:1068,credit:"USDA, domena publiczna",creditUrl:"https://commons.wikimedia.org/wiki/File:RD_CFDL-Lytle_Community_Health_Center_-_Community_Facility_Direct_Loan_(20171205-RD-LSC-0238).jpg"}},{heading:"Krok 5: zdj\u0119cia, kt\xF3re odpowiadaj\u0105 na pytania pacjenta",paragraphs:["Pacjent przed pierwsz\u0105 wizyt\u0105 chce wiedzie\u0107 trzy rzeczy: jak wygl\u0105da wej\u015Bcie, jak wygl\u0105da poczekalnia i kto go przyjmie. Na te pytania odpowiadaj\u0105 zdj\u0119cia. Wej\u015Bcie od ulicy, najlepiej z szyldem i numerem budynku, oszcz\u0119dza kr\u0105\u017Cenia wok\xF3\u0142 kamienicy. Poczekalnia i gabinet pokazuj\u0105 standard. Zdj\u0119cia zespo\u0142u buduj\u0105 zaufanie szybciej ni\u017C opis.","R\xF3b zdj\u0119cia w dzie\u0144, bez pacjent\xF3w w kadrze. Twarz osoby w poczekalni przychodni to informacja o jej zdrowiu, a na jej publikacj\u0119 potrzebna jest pisemna zgoda. Wgrywaj nowe zdj\u0119cia co kilka miesi\u0119cy. Profil z pi\u0119cioma zdj\u0119ciami sprzed czterech lat wygl\u0105da na porzucony, nawet je\u015Bli plac\xF3wka pracuje pe\u0142n\u0105 par\u0105."],bullets:["wej\u015Bcie od ulicy z widocznym szyldem i numerem","poczekalnia, rejestracja i przynajmniej jeden gabinet","zesp\xF3\u0142: lekarze i rejestracja, za zgod\u0105 os\xF3b na zdj\u0119ciach","logo i zdj\u0119cie w tle ustawione r\u0119cznie, nie wybrane przez Google","bez pacjent\xF3w w kadrze"],image:{src:"/blog/wizytowka-google-wejscie.jpg",alt:"Wej\u015Bcie do budynku kliniki od strony ulicy z widocznym zadaszeniem",width:1600,height:1067,credit:"Wikimedia Commons, CC0",creditUrl:"https://commons.wikimedia.org/wiki/File:Clinic_entrance,_Brown_Building,_McGill_University,_Oct_29_2022.jpg"}},{heading:"Krok 6: posty oraz pytania i odpowiedzi",paragraphs:["Posty w profilu to kr\xF3tkie komunikaty ze zdj\u0119ciem: nowy specjalista, zmiana godzin, szczepienia sezonowe, dost\u0119pne terminy. Pojedynczy post nie przesunie plac\xF3wki w wynikach, ale regularne publikowanie pokazuje pacjentowi i Google, \u017Ce profil kto\u015B prowadzi. Wystarczy jeden post na dwa tygodnie. Tre\u015B\u0107 podlega tym samym ograniczeniom co reklama \u015Bwiadcze\u0144 zdrowotnych: informujesz, nie zach\u0119casz i nie obiecujesz efektu.","Sekcj\u0119 pyta\u0144 i odpowiedzi mo\u017Ce wype\u0142ni\u0107 ka\u017Cdy u\u017Cytkownik Google, tak\u017Ce w imieniu plac\xF3wki. Zajrzyj tam i odpowiedz na pytania, kt\xF3re ju\u017C wisz\u0105. Potem dodaj z konta plac\xF3wki pi\u0119\u0107 pyta\u0144, kt\xF3re rejestracja s\u0142yszy codziennie: czy jest NFZ, czy potrzebne jest skierowanie, gdzie zaparkowa\u0107, ile trwa pierwsza wizyta, czy przyjmujecie dzieci. Ka\u017Cda odpowied\u017A to jeden telefon mniej do rejestracji."],link:{path:"/wiedza/reklama-swiadczen-zdrowotnych-co-wolno",label:"Reklama \u015Bwiadcze\u0144 zdrowotnych: co wolno",description:"Posty w profilu podlegaj\u0105 tym samym przepisom co ulotka."}},{heading:"Krok 7: sprawdzaj statystyki raz w miesi\u0105cu",paragraphs:["Panel Profilu Firmy pokazuje liczb\u0119 po\u0142\u0105cze\u0144, klikni\u0119\u0107 w tras\u0119 i wej\u015B\u0107 na stron\u0119 oraz zapytania, na kt\xF3re profil si\u0119 wy\u015Bwietli\u0142. Zapisuj te liczby co miesi\u0105c w prostej tabeli. Po trzech miesi\u0105cach zobaczysz, czy zmiany kategorii, us\u0142ug i zdj\u0119\u0107 prze\u0142o\u017Cy\u0142y si\u0119 na telefony.","Je\u015Bli po\u0142\u0105cze\u0144 jest du\u017Co, a nowych pacjent\xF3w nie przybywa, problem le\u017Cy zwykle poza profilem: w nieodebranych telefonach albo w braku wolnych termin\xF3w. Wizyt\xF3wka \u015Bci\u0105ga pacjenta do s\u0142uchawki, dalej przejmuje rejestracja."]}],faq:[{question:"Czy wizyt\xF3wka Google dla przychodni jest p\u0142atna?",answer:"Nie. Profil Firmy w Google jest bezp\u0142atny, a jego za\u0142o\u017Cenie, weryfikacja i prowadzenie nie wymagaj\u0105 \u017Cadnych op\u0142at. P\u0142atne s\u0105 jedynie reklamy Google Ads, kt\xF3re mog\u0105 wy\u015Bwietla\u0107 si\u0119 obok wynik\xF3w lokalnych, ale nie s\u0105 potrzebne, \u017Ceby profil dzia\u0142a\u0142."},{question:"Jak\u0105 kategori\u0119 wybra\u0107 dla przychodni wielospecjalistycznej?",answer:'Jako kategori\u0119 g\u0142\xF3wn\u0105 wybierz specjalizacj\u0119, na kt\xF3rej plac\xF3wce najbardziej zale\u017Cy lub kt\xF3ra przynosi najwi\u0119cej przychodu. Pozosta\u0142e specjalizacje dodaj jako kategorie dodatkowe, maksymalnie dziewi\u0119\u0107. Og\xF3lna kategoria \u201EPrzychodnia" sprawdza si\u0119 jako dodatkowa, rzadko jako g\u0142\xF3wna.'},{question:"Czy ka\u017Cdy lekarz w przychodni mo\u017Ce mie\u0107 w\u0142asn\u0105 wizyt\xF3wk\u0119?",answer:"Wytyczne Google dopuszczaj\u0105 osobne profile lekarzy przyjmuj\u0105cych w plac\xF3wce, je\u015Bli przyjmuj\u0105 pacjent\xF3w pod tym adresem. W ma\u0142ej przychodni zwykle lepiej skupi\u0107 opinie i zdj\u0119cia na jednym profilu plac\xF3wki. Osobne profile lekarzy maj\u0105 sens przy znanych specjalistach, kt\xF3rych pacjenci szukaj\u0105 po nazwisku."},{question:"Jak d\u0142ugo trwa weryfikacja profilu w Google?",answer:"Weryfikacja wideo lub telefoniczna trwa zwykle od kilku godzin do kilku dni roboczych. List z kodem dociera w ci\u0105gu oko\u0142o dw\xF3ch tygodni. Zmiany w ju\u017C zweryfikowanym profilu, na przyk\u0142ad kategorii czy godzin, pojawiaj\u0105 si\u0119 w wynikach zazwyczaj w ci\u0105gu kilku dni."},{question:"Po jakim czasie wizyt\xF3wka zacznie przynosi\u0107 telefony?",answer:"Poprawki kategorii, us\u0142ug i godzin zaczynaj\u0105 dzia\u0142a\u0107 zwykle po dw\xF3ch do sze\u015Bciu tygodni. Efekt zale\u017Cy od odleg\u0142o\u015Bci pacjent\xF3w, liczby i \u015Bwie\u017Co\u015Bci opinii oraz od tego, jak dopracowane s\u0105 profile konkurencyjnych plac\xF3wek w okolicy."}],sources:[{label:"Wytyczne dotycz\u0105ce reprezentowania firmy w Google",url:"https://support.google.com/business/answer/3038177",publisher:"Pomoc Google"},{label:"Jak poprawi\u0107 pozycj\u0119 w wynikach lokalnych",url:"https://support.google.com/business/answer/7091",publisher:"Pomoc Google"}],related:[{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Poprowadzimy profil za Ciebie, z raportem widoczno\u015Bci w mapach co miesi\u0105c."},{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Opinie to drugi po trafno\u015Bci czynnik, kt\xF3ry decyduje o pozycji w mapach."},{path:"/wiedza/pozycjonowanie-kliniki-krok-po-kroku",label:"Jak samodzielnie wypromowa\u0107 klinik\u0119 w Google",description:"Wizyt\xF3wka jako jeden z sze\u015Bciu etap\xF3w widoczno\u015Bci w Google."}]},{slug:"social-media-dla-lekarzy",title:"Social media dla lekarzy",h1:"Social media dla lekarzy: co publikowa\u0107, czego nie wolno i jak prowadzi\u0107 profil",seoTitle:"Social media dla lekarzy i gabinet\xF3w: co publikowa\u0107, czego nie wolno | mediaso",seoDescription:"Jak lekarz, stomatolog czy fizjoterapeuta mo\u017Ce prowadzi\u0107 Instagram, Facebook i TikTok zgodnie z Kodeksem Etyki Lekarskiej: tematy post\xF3w, rytm publikacji, zgody i wiadomo\u015Bci.",datePublished:"2026-10-25",dateModified:"2026-10-25",readingMinutes:8,lead:"Profil lekarza w mediach spo\u0142eczno\u015Bciowych ma jedno zadanie: pacjent, kt\xF3ry us\u0142ysza\u0142 nazwisko od znajomego albo znalaz\u0142 je w wyszukiwarce, ma zobaczy\u0107 konkretn\u0105 osob\u0119, jej zakres przyj\u0119\u0107 i spos\xF3b pracy, zanim zadzwoni do rejestracji. Od 1 stycznia 2025 roku Kodeks Etyki Lekarskiej nie m\xF3wi ju\u017C o zakazie reklamowania si\u0119, tylko o informowaniu o dzia\u0142alno\u015Bci zawodowej, wi\u0119c pole do publikacji jest szersze ni\u017C kilka lat temu. Granice zosta\u0142y: lekarz nie mo\u017Ce przedstawia\u0107 si\u0119 jako najlepszy ani jedyny, deprecjonowa\u0107 innych lekarzy, obiecywa\u0107 efektu leczenia ani pokazywa\u0107 pacjent\xF3w bez pisemnej zgody. Poni\u017Cej opisujemy, jak wybra\u0107 mi\u0119dzy profilem lekarza a profilem gabinetu, kt\xF3re tematy przynosz\u0105 pacjent\xF3w w poszczeg\xF3lnych specjalizacjach, ile publikowa\u0107 i jak obs\u0142ugiwa\u0107 wiadomo\u015Bci, \u017Ceby nie ujawni\u0107 danych o zdrowiu.",sections:[{heading:"Profil lekarza czy profil gabinetu",paragraphs:["Lekarz, kt\xF3ry przyjmuje w jednym miejscu i jest twarz\u0105 gabinetu, zwykle nie potrzebuje dw\xF3ch profili. Jeden profil gabinetu prowadzony z perspektywy lekarza ma wi\u0119kszy zasi\u0119g ni\u017C dwa profile publikuj\u0105ce to samo. Osobny profil lekarza ma sens, gdy specjalista przyjmuje w kilku plac\xF3wkach, gdy buduje rozpoznawalno\u015B\u0107 w swojej dziedzinie albo gdy pacjenci szukaj\u0105 go po nazwisku.","Przy profilu lekarza ustal na starcie, co nale\u017Cy do niego, a co do plac\xF3wki. Tre\u015Bci o zakresie przyj\u0119\u0107, do\u015Bwiadczeniu i wyst\u0105pieniach s\u0105 jego. Komunikaty o godzinach, cenach i wolnych terminach nale\u017C\u0105 do plac\xF3wki. Ten podzia\u0142 chroni oba profile przy zmianie miejsca pracy."],bullets:["jeden gabinet, jeden lekarz: jeden profil gabinetu z lekarzem w roli g\u0142\xF3wnej","lekarz w kilku plac\xF3wkach: osobny profil lekarza i linki do miejsc przyj\u0119\u0107","przychodnia wieloosobowa: profil plac\xF3wki i kr\xF3tkie prezentacje specjalist\xF3w"]},{heading:"Co lekarz mo\u017Ce publikowa\u0107 po zmianie Kodeksu Etyki Lekarskiej",paragraphs:["Art. 71 obowi\u0105zuj\u0105cego Kodeksu Etyki Lekarskiej pozwala lekarzowi informowa\u0107 o dzia\u0142alno\u015Bci zawodowej, o ile forma i tre\u015B\u0107 pozostaj\u0105 zgodne z zasadami etyki. W praktyce to szeroki katalog tre\u015Bci, a wi\u0119kszo\u015B\u0107 z nich lepiej buduje zaufanie pacjenta ni\u017C has\u0142o reklamowe."],bullets:["zakres przyj\u0119\u0107: z czym przyj\u015B\u0107, z czym nie, czy potrzebne jest skierowanie","wykszta\u0142cenie, specjalizacje, szkolenia i wyst\u0105pienia na konferencjach","przebieg wizyty, badania lub zabiegu opisany rzeczowo","odpowiedzi na pytania, kt\xF3re pacjenci zadaj\u0105 w gabinecie","sprz\u0119t i metoda pracy opisane technicznie, bez superlatyw\xF3w","komunikaty organizacyjne: miejsca przyj\u0119\u0107, urlopy, nowe terminy"],link:{path:"/wiedza/reklama-swiadczen-zdrowotnych-co-wolno",label:"Reklama \u015Bwiadcze\u0144 zdrowotnych: co wolno",description:"Pe\u0142na lista dozwolonych i zakazanych sformu\u0142owa\u0144 z podstaw\u0105 prawn\u0105."}},{heading:"Czego nie publikowa\u0107",paragraphs:["Wi\u0119kszo\u015B\u0107 problem\xF3w bierze si\u0119 z format\xF3w, kt\xF3re dobrze dzia\u0142aj\u0105 w innych bran\u017Cach. Konkurs z zabiegiem w nagrod\u0119, rabat dla obserwuj\u0105cych czy metamorfoza przed i po pokazana jako dow\xF3d skuteczno\u015Bci to w medycynie zach\u0119ta do korzystania ze \u015Bwiadcze\u0144. Za taki materia\u0142 lekarz odpowiada przed rzecznikiem odpowiedzialno\u015Bci zawodowej, a plac\xF3wka na podstawie art. 147a Kodeksu wykrocze\u0144."],bullets:["superlatywy: najlepszy, jedyny, najnowocze\u015Bniejszy w mie\u015Bcie","obietnica lub gwarancja efektu leczenia","rabaty, kody zni\u017Ckowe, konkursy z zabiegiem w nagrod\u0119","zdj\u0119cia pacjent\xF3w i ich historie bez pisemnej zgody","polecanie suplement\xF3w, kosmetyk\xF3w i produkt\xF3w niezwi\u0105zanych z leczeniem","komentowanie pracy innych lekarzy w spos\xF3b, kt\xF3ry ich deprecjonuje"]},{heading:"Tematy, kt\xF3re przynosz\u0105 pacjent\xF3w w poszczeg\xF3lnych specjalizacjach",paragraphs:["Dobry temat to pytanie, kt\xF3re pacjent zadaje przed wizyt\u0105. Rejestracja i sam lekarz s\u0142ysz\u0105 je codziennie, wi\u0119c lista temat\xF3w na kwarta\u0142 powstaje w godzin\u0119 rozmowy. Og\xF3lne grafiki o zdrowym stylu \u017Cycia wype\u0142niaj\u0105 kalendarz, ale nie daj\u0105 powodu, \u017Ceby zadzwoni\u0107 akurat do tego gabinetu.","Stomatolog zyskuje najwi\u0119cej na tre\u015Bciach zdejmuj\u0105cych l\u0119k: jak wygl\u0105da znieczulenie, ile trwa leczenie kana\u0142owe, co dzieje si\u0119 na pierwszej wizycie dziecka. Fizjoterapeuta na kr\xF3tkim wideo z \u0107wiczeniem i wyja\u015Bnieniem, kiedy b\xF3l wymaga wizyty. Ginekolog na rzeczowym opisie bada\u0144 profilaktycznych i tego, jak si\u0119 do nich przygotowa\u0107. Dermatolog na tym, kiedy znami\u0119 wymaga kontroli i jak przebiega dermatoskopia."],bullets:["stomatolog: znieczulenie, leczenie kana\u0142owe, wizyta adaptacyjna dziecka, implanty krok po kroku","fizjoterapeuta: \u0107wiczenia na wideo, pierwsza wizyta, kiedy i\u015B\u0107 do lekarza","ginekolog: badania profilaktyczne, przygotowanie do wizyty, prowadzenie ci\u0105\u017Cy","dermatolog: kontrola znamion, dermatoskopia, przygotowanie do zabiegu","psycholog i psychiatra: jak wygl\u0105da pierwsza konsultacja, czym r\xF3\u017Cni\u0105 si\u0119 specjali\u015Bci"]},{heading:"Ile publikowa\u0107 i ile to zajmuje czasu",paragraphs:["Dwie do czterech publikacji tygodniowo utrzymuj\u0105 profil w rotacji. Poni\u017Cej jednej tygodniowo profil wygl\u0105da na porzucony, a pacjent szukaj\u0105cy \u015Bladu, \u017Ce gabinet dzia\u0142a, go nie znajduje. Kr\xF3tkie wideo z lekarzem zwykle dociera do wi\u0119kszej liczby os\xF3b ni\u017C grafika, bo pokazuje cz\u0142owieka, z kt\xF3rym pacjent b\u0119dzie rozmawia\u0142.","Najmniej czasu lekarza zabiera rytm miesi\u0119czny: jedna sesja nagraniowa na godzin\u0119 lub dwie, z kt\xF3rej powstaje materia\u0142 na ca\u0142y miesi\u0105c, plan tre\u015Bci zatwierdzany z wyprzedzeniem i publikacja roz\u0142o\u017Cona w kalendarzu. Monta\u017C, opisy, grafiki i harmonogram mo\u017Ce przej\u0105\u0107 asystentka albo agencja."]},{heading:"Wiadomo\u015Bci i komentarze od pacjent\xF3w",paragraphs:["Pacjenci pisz\u0105 na Instagramie i Messengerze o objawy, wyniki i terminy. Odpowied\u017A z porad\u0105 medyczn\u0105 w wiadomo\u015Bci jest ryzykowna: lekarz nie widzia\u0142 pacjenta, a historia rozmowy zostaje na serwerach platformy. Bezpieczny standard to przekierowanie do rejestracji lub na wizyt\u0119, z informacj\u0105, jak si\u0119 um\xF3wi\u0107.","W komentarzach obowi\u0105zuje ta sama zasada co przy opiniach w Google. Nie potwierdzasz publicznie, \u017Ce kto\u015B jest pacjentem, i nie odnosisz si\u0119 do przebiegu leczenia, nawet gdy autor sam o nim pisze. Samo potwierdzenie wizyty jest ujawnieniem danych o zdrowiu."],link:{path:"/wiedza/rodo-w-marketingu-placowki-medycznej",label:"RODO w marketingu plac\xF3wki medycznej",description:"Zgody na wizerunek, opinie i obs\u0142uga wiadomo\u015Bci od pacjent\xF3w."}},{heading:"Kiedy zleci\u0107 prowadzenie profilu",paragraphs:["Samodzielne prowadzenie profilu dzia\u0142a, dop\xF3ki lekarz ma na nie sta\u0142y czas w tygodniu. Kiedy publikacje zaczynaj\u0105 si\u0119 urywa\u0107 na kilka tygodni, lepiej odda\u0107 monta\u017C, grafiki, harmonogram i moderacj\u0119 komu\u015B, kto zna ograniczenia bran\u017Cy, a sobie zostawi\u0107 nagrania i akceptacj\u0119 tre\u015Bci. Akceptacja zawsze zostaje po stronie lekarza, bo to on odpowiada zawodowo za tre\u015B\u0107 publikowan\u0105 w jego imieniu."],link:{path:"/uslugi/social-media-dla-klinik",label:"Prowadzenie social medi\xF3w dla lekarzy i klinik",description:"Plan tre\u015Bci, nagrania w gabinecie, monta\u017C i obs\u0142uga wiadomo\u015Bci."}}],faq:[{question:"Czy lekarz mo\u017Ce prowadzi\u0107 konto na Instagramie lub TikToku?",answer:"Tak. Kodeks Etyki Lekarskiej obowi\u0105zuj\u0105cy od 1 stycznia 2025 roku pozwala lekarzowi informowa\u0107 o dzia\u0142alno\u015Bci zawodowej w ka\u017Cdej formie przekazu, w tym w mediach spo\u0142eczno\u015Bciowych. Tre\u015B\u0107 musi pozosta\u0107 rzetelna: bez superlatyw\xF3w, obietnic efektu leczenia, deprecjonowania innych lekarzy i promowania produkt\xF3w niezwi\u0105zanych z medycyn\u0105."},{question:"Czy lekarz mo\u017Ce pokazywa\u0107 pacjent\xF3w w social mediach?",answer:"Tylko za pisemn\u0105 zgod\u0105 pacjenta, kt\xF3ra wskazuje kana\u0142y publikacji i daje mo\u017Cliwo\u015B\u0107 wycofania. Sam wizerunek osoby w gabinecie ujawnia informacj\u0119 o korzystaniu ze \u015Bwiadcze\u0144 zdrowotnych, czyli dane szczeg\xF3lnej kategorii. Bez zgody publikuje si\u0119 zesp\xF3\u0142, wn\u0119trza, sprz\u0119t i modele anatomiczne."},{question:"Ile post\xF3w tygodniowo powinien publikowa\u0107 lekarz?",answer:"Dwie do czterech publikacji tygodniowo wystarcz\u0105, \u017Ceby profil wygl\u0105da\u0142 na aktywny i by\u0142 widoczny dla obserwuj\u0105cych. Regularno\u015B\u0107 ma wi\u0119ksze znaczenie ni\u017C liczba: dwa posty co tydzie\u0144 przez rok daj\u0105 wi\u0119cej ni\u017C dziesi\u0119\u0107 w jednym miesi\u0105cu i przerwa na kwarta\u0142."},{question:"Czy lekarz mo\u017Ce odpowiada\u0107 na pytania pacjent\xF3w w wiadomo\u015Bciach?",answer:"Na pytania organizacyjne tak: o terminy, miejsca przyj\u0119\u0107 i przygotowanie do wizyty. Pytania o objawy i wyniki lepiej przekierowa\u0107 na wizyt\u0119 lub teleporad\u0119, bo porada udzielona w wiadomo\u015Bci odbywa si\u0119 bez badania i bez dokumentacji medycznej."}],sources:[{label:"Kodeks Etyki Lekarskiej",url:"https://nil.org.pl/dla-lekarzy/prawo/kodeks-etyki-lekarskiej",publisher:"Naczelna Izba Lekarska"},{label:"Informowanie o dzia\u0142alno\u015Bci leczniczej a jej reklama",url:"https://nil.org.pl/dla-lekarzy/praktyka-lekarska/4240-informowanie-o-dzialalnosci-leczniczej-a-jej-reklama",publisher:"Naczelna Izba Lekarska"}],related:[{path:"/uslugi/social-media-dla-klinik",label:"Social media dla klinik, gabinet\xF3w i lekarzy",description:"Prowadzimy profile lekarzy i plac\xF3wek z akceptacj\u0105 tre\u015Bci po stronie lekarza."},{path:"/wiedza/reklama-swiadczen-zdrowotnych-co-wolno",label:"Reklama \u015Bwiadcze\u0144 zdrowotnych: co wolno",description:"Granica mi\u0119dzy informacj\u0105 a reklam\u0105 w przepisach."},{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Opinie w Google i komentarze w social mediach rz\u0105dz\u0105 si\u0119 tymi samymi zasadami."}]},{slug:"czym-jest-marketing-medyczny",title:"Czym jest marketing medyczny",h1:"Czym jest marketing medyczny i czym r\xF3\u017Cni si\u0119 od zwyk\u0142ego marketingu",seoTitle:"Czym jest marketing medyczny - definicja i zasady | mediaso",seoDescription:"Marketing medyczny to informowanie o us\u0142ugach plac\xF3wki w granicach przepis\xF3w o reklamie \u015Bwiadcze\u0144 zdrowotnych. Wyja\u015Bniamy zakres, ograniczenia i kana\u0142y.",datePublished:"2026-08-29",dateModified:"2026-09-22",readingMinutes:7,lead:"Marketing medyczny to ca\u0142o\u015B\u0107 dzia\u0142a\u0144, kt\xF3rymi plac\xF3wka zdrowotna informuje pacjent\xF3w o swoich us\u0142ugach, dost\u0119pno\u015Bci i kompetencjach zespo\u0142u, prowadzonych w granicach przepis\xF3w ograniczaj\u0105cych reklam\u0119 \u015Bwiadcze\u0144 zdrowotnych. Od marketingu w innych bran\u017Cach r\xF3\u017Cni go przede wszystkim to, czego nie wolno: nie mo\u017Cna obiecywa\u0107 efektu leczenia, zach\u0119ca\u0107 do korzystania ze \u015Bwiadcze\u0144 w spos\xF3b nachalny, wykorzystywa\u0107 wizerunku pacjenta bez pisemnej zgody ani budowa\u0107 przekazu na por\xF3wnaniach z konkretnymi plac\xF3wkami. Zostaje bardzo du\u017Co miejsca na komunikacj\u0119 opart\u0105 na faktach: zakres us\u0142ug, ceny, terminy, kwalifikacje specjalist\xF3w, przebieg wizyty, przygotowanie do bada\u0144. Praktyka pokazuje, \u017Ce to w\u0142a\u015Bnie ta rzeczowa warstwa przynosi plac\xF3wkom najwi\u0119cej kontakt\xF3w, bo odpowiada na pytania, kt\xF3re pacjent zadaje przed telefonem.",sections:[{heading:"Co mie\u015Bci si\u0119 w marketingu medycznym",paragraphs:['Zakres jest szerszy, ni\u017C sugeruje s\u0142owo \u201Ereklama". Obejmuje stron\u0119 internetow\u0105 plac\xF3wki i jej widoczno\u015B\u0107 w wyszukiwarce, Profil Firmy w Google z opiniami pacjent\xF3w, profile w mediach spo\u0142eczno\u015Bciowych, materia\u0142y drukowane w poczekalni, komunikacj\u0119 SMS i e-mail z pacjentami oraz spos\xF3b, w jaki rejestracja odbiera telefon.',"Ostatni punkt bywa pomijany, a to on rozstrzyga wynik. Kampania, kt\xF3ra generuje telefony w godzinach, gdy nikt ich nie odbiera, jest wydatkiem bez efektu. Dlatego marketing plac\xF3wki zaczyna si\u0119 od sprawdzenia, co si\u0119 dzieje z pacjentem, kt\xF3ry ju\u017C pr\xF3buje si\u0119 skontaktowa\u0107."],bullets:["strona internetowa z podstronami us\u0142ug i cennikiem","widoczno\u015B\u0107 w wyszukiwarce na zapytania lokalne i us\u0142ugowe","Profil Firmy w Google: kategorie, godziny, zdj\u0119cia, opinie","media spo\u0142eczno\u015Bciowe i obs\u0142uga wiadomo\u015Bci od pacjent\xF3w","komunikacja z pacjentami: potwierdzenia, przypomnienia, zaproszenia na kontrole","obs\u0142uga telefonu w rejestracji jako ostatni etap \u015Bcie\u017Cki"]},{heading:"Granice prawne w skr\xF3cie",paragraphs:["Reklama dzia\u0142alno\u015Bci leczniczej jest w Polsce ograniczona. Podmiot leczniczy mo\u017Ce podawa\u0107 do wiadomo\u015Bci publicznej informacje o zakresie i rodzajach udzielanych \u015Bwiadcze\u0144, ale forma i tre\u015B\u0107 tych informacji nie mo\u017Ce mie\u0107 cech zach\u0119ty do korzystania ze \u015Bwiadcze\u0144. Lekarzy dodatkowo wi\u0105\u017Ce kodeks etyki lekarskiej, a apteki i wyroby medyczne maj\u0105 w\u0142asne, ostrzejsze re\u017Cimy.","W praktyce dzieli to komunikaty na dwie grupy. Bezpieczne: opis us\u0142ugi, cena, czas trwania, przygotowanie, kwalifikacje lekarza, dost\u0119pne terminy, wyposa\u017Cenie. Ryzykowne: obietnice wyniku, przekaz oparty na strachu, promocje w stylu handlowym, por\xF3wnania z konkurencj\u0105 po nazwie, przed i po bez zgody i kontekstu."],note:"To skr\xF3t, nie opinia prawna. Przy us\u0142ugach z pogranicza - medycyna estetyczna, stomatologia komercyjna - warto skonsultowa\u0107 materia\u0142y z prawnikiem bran\u017Cowym.",link:{path:"/wiedza/reklama-swiadczen-zdrowotnych-co-wolno",label:"Reklama \u015Bwiadcze\u0144 zdrowotnych: co wolno",description:"Art. 14, Kodeks Etyki Lekarskiej i wyroby medyczne w jednym miejscu."}},{heading:"Sk\u0105d realnie przychodz\u0105 pacjenci",paragraphs:["W wi\u0119kszo\u015Bci plac\xF3wek, kt\xF3rym pomagamy, najsilniejszym kana\u0142em jest wyszukiwarka razem z mapami. Pacjent szuka konkretnej us\u0142ugi w konkretnej okolicy, sprawdza opinie i dzwoni do jednej z trzech pierwszych plac\xF3wek na li\u015Bcie. Drugim kana\u0142em jest polecenie - i tu te\u017C ko\u0144czy si\u0119 w Google, bo pacjent weryfikuje polecan\u0105 plac\xF3wk\u0119, zanim zadzwoni.","Media spo\u0142eczno\u015Bciowe rzadko generuj\u0105 pierwszy kontakt, ale pracuj\u0105 na decyzj\u0119: pacjent sprawdza profil i szuka \u015Bladu, \u017Ce plac\xF3wka dzia\u0142a. Reklama p\u0142atna dzia\u0142a wtedy, gdy jest po co dzwoni\u0107 - s\u0105 wolne terminy i kto\u015B odbiera telefon."]},{heading:"Od czego zacz\u0105\u0107 w ma\u0142ej plac\xF3wce",paragraphs:["Kolejno\u015B\u0107, kt\xF3ra daje najwi\u0119cej przy najmniejszym bud\u017Cecie, jest za ka\u017Cdym razem podobna. Najpierw wizyt\xF3wka Google: w\u0142a\u015Bciwa kategoria, komplet godzin, zdj\u0119cia, opisy us\u0142ug. Potem opinie - systemowa pro\u015Bba po wizycie, kierowana do wszystkich pacjent\xF3w. Potem strona z podstronami us\u0142ug i cennikiem.","Reklama p\u0142atna jest ostatnia, nie pierwsza. Uruchomiona przed uporz\u0105dkowaniem tych trzech rzeczy podnosi koszt pozyskania pacjenta i maskuje problem, zamiast go rozwi\u0105za\u0107."],bullets:["wizyt\xF3wka Google z poprawn\u0105 kategori\u0105 g\u0142\xF3wn\u0105","proces zbierania opinii po wizycie","podstrona dla ka\u017Cdej us\u0142ugi, kt\xF3r\u0105 plac\xF3wka sprzedaje","pomiar nieodebranych po\u0142\u0105cze\u0144 w rejestracji","dopiero potem kampanie p\u0142atne"]},{heading:"Jak mierzy\u0107, czy to dzia\u0142a",paragraphs:["Zasi\u0119gi i polubienia nie s\u0105 wynikiem. Liczby, kt\xF3re maj\u0105 znaczenie dla w\u0142a\u015Bciciela plac\xF3wki, to liczba po\u0142\u0105cze\u0144 i formularzy, odsetek po\u0142\u0105cze\u0144 odebranych, liczba um\xF3wionych wizyt oraz udzia\u0142 pacjent\xF3w pierwszorazowych.","Minimalny zestaw narz\u0119dzi jest darmowy: Google Search Console pokazuje zapytania i wej\u015Bcia z wyszukiwarki, statystyki Profilu Firmy pokazuj\u0105 telefony i klikni\u0119cia w tras\u0119, a raport z centrali telefonicznej pokazuje, ile z tych telefon\xF3w zosta\u0142o odebranych. Trzy \u017Ar\xF3d\u0142a wystarcz\u0105, \u017Ceby przesta\u0107 zgadywa\u0107."]}],faq:[{question:"Czy plac\xF3wka medyczna mo\u017Ce si\u0119 reklamowa\u0107 w Polsce?",answer:"Mo\u017Ce informowa\u0107 o zakresie i rodzajach udzielanych \u015Bwiadcze\u0144, cenach, dost\u0119pno\u015Bci i kwalifikacjach zespo\u0142u. Ograniczenia dotycz\u0105 formy: przekaz nie mo\u017Ce mie\u0107 cech zach\u0119ty do korzystania ze \u015Bwiadcze\u0144 ani obiecywa\u0107 efektu leczenia. Rzetelna informacja o us\u0142udze jest dozwolona i to na niej opiera si\u0119 skuteczna komunikacja plac\xF3wek."},{question:"Ile kosztuje marketing medyczny w ma\u0142ej przychodni?",answer:"Pierwsze kroki - uporz\u0105dkowanie wizyt\xF3wki Google i proces zbierania opinii - kosztuj\u0105 prac\u0119, nie bud\u017Cet mediowy. Sta\u0142a obs\u0142uga social medi\xF3w i strona internetowa to koszty zale\u017Cne od zakresu: liczby kana\u0142\xF3w, publikacji i podstron. Bud\u017Cet reklamowy zale\u017Cy od tego, ile wolnych termin\xF3w plac\xF3wka ma do zape\u0142nienia."},{question:"Czy marketing medyczny to to samo co SEO?",answer:"Nie. SEO jest jego cz\u0119\u015Bci\u0105 i odpowiada za widoczno\u015B\u0107 w wynikach wyszukiwania. Marketing medyczny obejmuje te\u017C wizyt\xF3wk\u0119 Google, social media, komunikacj\u0119 z pacjentami i obs\u0142ug\u0119 zg\u0142osze\u0144 w rejestracji."}],sources:[{label:"Ustawa z dnia 15 kwietnia 2011 r. o dzia\u0142alno\u015Bci leczniczej",url:"https://eli.gov.pl/eli/DU/2011/654/ogl",publisher:"Dziennik Ustaw"},{label:"Informowanie o dzia\u0142alno\u015Bci leczniczej a jej reklama",url:"https://nil.org.pl/dla-lekarzy/praktyka-lekarska/4240-informowanie-o-dzialalnosci-leczniczej-a-jej-reklama",publisher:"Naczelna Izba Lekarska"}],related:[{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie klinik",description:"Najmocniejszy kana\u0142 pozyskiwania pacjent\xF3w rozbity na etapy."},{path:"/wiedza/rodo-w-marketingu-placowki-medycznej",label:"RODO w marketingu plac\xF3wki medycznej",description:"Zgody, wizerunek i dane pacjent\xF3w w materia\u0142ach marketingowych."},{path:"/wiedza/reklama-swiadczen-zdrowotnych-co-wolno",label:"Reklama \u015Bwiadcze\u0144 zdrowotnych: co wolno",description:"Granica mi\u0119dzy informacj\u0105 a reklam\u0105 w przepisach, z list\u0105 zakazanych sformu\u0142owa\u0144."},{path:"/diagnostyka",label:"Diagnostyka wzrostu plac\xF3wki",description:"Sprawd\u017A w 20 pytaniach, kt\xF3ry etap \u015Bcie\u017Cki pacjenta si\u0119 urywa."}]},{slug:"pozycjonowanie-kliniki-krok-po-kroku",title:"Jak samodzielnie wypromowa\u0107 klinik\u0119 w Google",h1:"Jak samodzielnie wypromowa\u0107 klinik\u0119 w Google: 6 krok\xF3w",seoTitle:"Jak samodzielnie wypromowa\u0107 klinik\u0119 w Google - 6 krok\xF3w | mediaso",seoDescription:"Poradnik dla w\u0142a\u015Bciciela plac\xF3wki: lista fraz z Search Console, indeksowanie, podstrony us\u0142ug, wizyt\xF3wka Google, tre\u015Bci i pomiar. Do zrobienia bez agencji.",datePublished:"2026-08-29",dateModified:"2026-10-25",readingMinutes:9,lead:"Pozycjonowanie kliniki daje si\u0119 roz\u0142o\u017Cy\u0107 na sze\u015B\u0107 krok\xF3w wykonywanych po kolei, a nie r\xF3wnolegle. Najpierw ustalasz, na jakie zapytania pacjenci realnie szukaj\u0105 twoich us\u0142ug w twoim mie\u015Bcie. Potem sprawdzasz, czy strona w og\xF3le jest indeksowana i jak d\u0142ugo si\u0119 \u0142aduje na telefonie. Trzeci krok to rozbicie oferty na osobne podstrony - jedna us\u0142uga, jeden adres. Czwarty to wizyt\xF3wka Google, kt\xF3ra w medycynie odpowiada za wi\u0119kszo\u015B\u0107 ruchu lokalnego. Pi\u0105ty to tre\u015B\u0107 odpowiadaj\u0105ca na pytania zadawane przed wizyt\u0105. Sz\xF3sty to pomiar: pozycje, wej\u015Bcia i telefony. Ta kolejno\u015B\u0107 ma znaczenie, bo ka\u017Cdy krok korzysta z poprzedniego. Publikowanie tre\u015Bci na stronie, kt\xF3rej Google nie indeksuje, jest prac\u0105 wyrzucon\u0105 w b\u0142oto.",sections:[{heading:"Krok 1: lista fraz z podzia\u0142em na intencje",paragraphs:["Zacznij od Google Search Console. W raporcie skuteczno\u015Bci zobaczysz, na jakie zapytania strona ju\u017C si\u0119 wy\u015Bwietla i na kt\xF3rych pozycjach. Frazy z pozycji 8-20 to najta\u0144szy wzrost, jaki masz do wzi\u0119cia - Google ju\u017C uznaje stron\u0119 za sensown\u0105 odpowied\u017A, brakuje niewiele.","Do tego dopisz zapytania, kt\xF3rych pacjenci u\u017Cywaj\u0105, a kt\xF3rych na li\u015Bcie nie ma. Najpro\u015Bciej zebra\u0107 je od rejestracji: to zestaw pyta\u0144 padaj\u0105cych codziennie przez telefon. Podziel ca\u0142o\u015B\u0107 na trzy grupy: zapytania us\u0142ugowe z miastem, zapytania o cen\u0119 i zapytania informacyjne o przebiegu zabiegu."]},{heading:"Krok 2: sprawd\u017A, czy Google widzi twoj\u0105 stron\u0119",paragraphs:['Wpisz w wyszukiwark\u0119 \u201Esite:" i adres swojej domeny. Je\u017Celi wynik pokazuje mniej stron, ni\u017C ich naprawd\u0119 masz, cz\u0119\u015B\u0107 serwisu nie jest zaindeksowana. W Search Console znajdziesz pow\xF3d w raporcie indeksowania.',"Drugi test: otw\xF3rz stron\u0119 na telefonie w zasi\u0119gu 4G i policz, ile sekund mija do pojawienia si\u0119 tre\u015Bci. Powy\u017Cej trzech sekund tracisz pacjent\xF3w jeszcze przed wej\u015Bciem. Trzeci test: wy\u0142\u0105cz JavaScript w przegl\u0105darce. Je\u017Celi strona jest pusta, wyszukiwarka ma z ni\u0105 k\u0142opot podobny do twojego."],bullets:['sprawd\u017A liczb\u0119 zaindeksowanych podstron zapytaniem \u201Esite:"',"przejrzyj raport indeksowania w Google Search Console","zmierz czas \u0142adowania na telefonie, nie na komputerze w biurze","sprawd\u017A, czy ka\u017Cda podstrona ma w\u0142asny tytu\u0142 i opis"]},{heading:"Krok 3: jedna us\u0142uga, jeden adres",paragraphs:['To jest zmiana o najwi\u0119kszym wp\u0142ywie i jednocze\u015Bnie ta, kt\xF3r\u0105 plac\xF3wki odk\u0142adaj\u0105 najd\u0142u\u017Cej. Strona \u201ENasze us\u0142ugi" z list\u0105 dwudziestu punkt\xF3w nie zarankuje na \u017Cadn\u0105 z nich. Google przypisuje wynik do adresu, wi\u0119c ka\u017Cda us\u0142uga potrzebuje w\u0142asnego.',"Zacznij od trzech us\u0142ug o najwi\u0119kszej warto\u015Bci. Ka\u017Cda dostaje: opis przebiegu wizyty, czas trwania, cen\u0119 lub przedzia\u0142 cenowy, przygotowanie pacjenta, przeciwwskazania, informacj\u0119 o tym, kto j\u0105 wykonuje, i sekcj\u0119 z pytaniami. To zwykle 600-1000 s\u0142\xF3w napisanych konkretnie, bez wst\u0119p\xF3w o trosce o zdrowie."]},{heading:"Krok 4: wizyt\xF3wka Google",paragraphs:['W medycynie mapy odpowiadaj\u0105 za wi\u0119kszo\u015B\u0107 kontakt\xF3w lokalnych. Ustaw kategori\u0119 g\u0142\xF3wn\u0105 na t\u0119 us\u0142ug\u0119, na kt\xF3rej najbardziej ci zale\u017Cy - kategoria \u201Eprzychodnia" nie wy\u015Bwietli ci\u0119 na zapytanie o konkretnego specjalist\u0119. Uzupe\u0142nij kategorie dodatkowe, list\u0119 us\u0142ug, godziny \u0142\u0105cznie ze \u015Bwi\u0119tami, zdj\u0119cia wej\u015Bcia od ulicy i wn\u0119trz.',"Potem opinie. Popro\u015B o nie wszystkich pacjent\xF3w z danej grupy, nie tylko zadowolonych, i nie oferuj niczego w zamian. Odpowiadaj na ka\u017Cd\u0105, tak\u017Ce negatywn\u0105, nie potwierdzaj\u0105c publicznie, \u017Ce autor by\u0142 pacjentem - to informacja o jego zdrowiu."],link:{path:"/wiedza/wizytowka-google-dla-przychodni",label:"Wizyt\xF3wka Google dla przychodni",description:"Kategoria, us\u0142ugi, zdj\u0119cia i posty krok po kroku."}},{heading:"Krok 5: tre\u015B\u0107, kt\xF3ra odpowiada na pytania",paragraphs:["Artyku\u0142y w bazie wiedzy pracuj\u0105 na zapytania zadawane przed decyzj\u0105: ile trwa leczenie, jak si\u0119 przygotowa\u0107, co obejmuje cena, kiedy zg\u0142osi\u0107 si\u0119 pilnie. Napisz je j\u0119zykiem pacjenta, nie j\u0119zykiem opisu procedury z podr\u0119cznika.","Ka\u017Cdy tekst medyczny powinien przej\u015B\u0107 przez lekarza z plac\xF3wki. To nie tylko kwestia bezpiecze\u0144stwa - autorstwo i nadz\xF3r merytoryczny s\u0105 sygna\u0142em jako\u015Bci dla wyszukiwarki, kt\xF3ra przy tematach zdrowotnych ocenia wiarygodno\u015B\u0107 \u017Ar\xF3d\u0142a ostrzej ni\u017C gdzie indziej."],bullets:["artyku\u0142 na ka\u017Cde powtarzalne pytanie z rejestracji","podpis autora i osoby, kt\xF3ra sprawdzi\u0142a tre\u015B\u0107 merytorycznie","link z artyku\u0142u do podstrony us\u0142ugi, kt\xF3rej dotyczy","aktualizacja daty przy realnej zmianie tre\u015Bci, nie co miesi\u0105c"]},{heading:"Krok 6: pomiar",paragraphs:["Raz w miesi\u0105cu zapisuj cztery liczby: pozycje na uzgodnionej li\u015Bcie fraz, wej\u015Bcia z wyszukiwarki, telefony i klikni\u0119cia w tras\u0119 z wizyt\xF3wki oraz liczb\u0119 nowych pacjent\xF3w. Bez tego nie odr\xF3\u017Cnisz efektu sezonu od efektu pracy.","Pierwszych ruch\xF3w spodziewaj si\u0119 po 6-10 tygodniach na frazach lokalnych. Frazy og\xF3lne w du\u017Cym mie\u015Bcie wymagaj\u0105 kwarta\u0142\xF3w. Je\u017Celi po p\xF3\u0142 roku systematycznej pracy nic si\u0119 nie rusza, problem le\u017Cy zwykle w tym, \u017Ce konkurencja ma dziesi\u0105tki podstron, a ty trzy."],link:{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie kliniki: zakres naszej us\u0142ugi",description:"Audyt, architektura podstron, tre\u015B\u0107 i raport z pozycji co miesi\u0105c."}}],faq:[{question:"Ile kosztuje pozycjonowanie kliniki?",answer:"Sta\u0142a obs\u0142uga SEO dla plac\xF3wki lokalnej to zwykle wydatek rz\u0119du kilku tysi\u0119cy z\u0142otych netto miesi\u0119cznie, zale\u017Cnie od liczby us\u0142ug i konkurencji w mie\u015Bcie. Cz\u0119\u015B\u0107 pracy - wizyt\xF3wka Google, opinie, uzupe\u0142nienie tre\u015Bci - da si\u0119 wykona\u0107 w\u0142asnymi si\u0142ami i to od niej warto zacz\u0105\u0107."},{question:"Czy da si\u0119 pozycjonowa\u0107 klinik\u0119 samodzielnie?",answer:"Kroki 1, 2 i 4 z tego poradnika wykonuje si\u0119 bez wiedzy technicznej i one daj\u0105 najwi\u0119cej na start. Rozbicie oferty na podstrony i praca nad tre\u015Bci\u0105 wymagaj\u0105 wi\u0119cej czasu ni\u017C umiej\u0119tno\u015Bci. Zewn\u0119trzne wsparcie zwykle przyspiesza, ale nie jest warunkiem pierwszych efekt\xF3w."},{question:"Jak d\u0142ugo czeka si\u0119 na efekty SEO w bran\u017Cy medycznej?",answer:"Frazy lokalne o niskiej konkurencji ruszaj\u0105 zwykle po 6-10 tygodniach od wdro\u017Cenia zmian. Zapytania og\xF3lne w du\u017Cych miastach zajmuj\u0105 od dw\xF3ch do czterech kwarta\u0142\xF3w. Tempo zale\u017Cy g\u0142\xF3wnie od tego, ile podstron ma konkurencja i od jak dawna publikuje."}],sources:[{label:"Google Search Essentials",url:"https://developers.google.com/search/docs/essentials",publisher:"Google Search Central"},{label:"Jak poprawi\u0107 pozycj\u0119 w wynikach lokalnych",url:"https://support.google.com/business/answer/7091",publisher:"Pomoc Google"}],related:[{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie klinik",description:"Ten sam proces prowadzony przez nas, z raportowaniem co miesi\u0105c."},{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Krok czwarty rozpisany na szczeg\xF3\u0142y."},{path:"/wiedza/ile-kosztuje-strona-dla-przychodni",label:"Ile kosztuje strona internetowa dla przychodni",description:"Z czego sk\u0142ada si\u0119 wycena i co realnie wp\u0142ywa na cen\u0119."}]},{slug:"rodo-w-marketingu-placowki-medycznej",title:"RODO w marketingu plac\xF3wki medycznej",h1:"RODO w marketingu plac\xF3wki medycznej",seoTitle:"RODO w marketingu plac\xF3wki medycznej | mediaso",seoDescription:"Zgody na wizerunek, opinie pacjent\xF3w, SMS-y marketingowe, umowy powierzenia z agencj\u0105 i piksele reklamowe. Co plac\xF3wka musi mie\u0107 na pi\u015Bmie.",datePublished:"2026-08-29",dateModified:"2026-09-22",readingMinutes:8,lead:"W plac\xF3wce medycznej niemal ka\u017Cdy materia\u0142 marketingowy dotyka danych szczeg\xF3lnej kategorii, bo sam fakt korzystania ze \u015Bwiadcze\u0144 zdrowotnych jest informacj\u0105 o zdrowiu. Dlatego zdj\u0119cie pacjenta w poczekalni, publiczna odpowied\u017A na opini\u0119 potwierdzaj\u0105ca, \u017Ce kto\u015B by\u0142 u was na wizycie, czy SMS z zaproszeniem na badanie kontrolne wymagaj\u0105 innej ostro\u017Cno\u015Bci ni\u017C analogiczne dzia\u0142ania w restauracji. Regu\u0142a praktyczna brzmi: nie publikuj i nie wysy\u0142aj niczego, co pozwala powi\u0105za\u0107 konkretn\u0105 osob\u0119 z korzystaniem z twoich us\u0142ug, dop\xF3ki nie masz na to zgody na pi\u015Bmie. Druga regu\u0142a dotyczy dostawc\xF3w: agencja, infolinia i firma wysy\u0142aj\u0105ca SMS-y przetwarzaj\u0105 dane w twoim imieniu, wi\u0119c potrzebujesz z nimi umowy powierzenia przetwarzania.",sections:[{heading:"Zgoda na wizerunek: co musi w niej by\u0107",paragraphs:["Zgoda ustna nie wystarczy, bo w razie sporu nie da si\u0119 jej wykaza\u0107. Dokument powinien wskazywa\u0107, kto publikuje, jakie materia\u0142y, w jakich kana\u0142ach i przez jaki czas, oraz zawiera\u0107 informacj\u0119 o prawie wycofania zgody w dowolnym momencie.","Osobno traktuj zdj\u0119cia przed i po. Pokazuj\u0105 one nie tylko wizerunek, ale te\u017C przebieg leczenia, wi\u0119c zgoda musi to obejmowa\u0107 wprost. Wycofanie zgody oznacza usuni\u0119cie materia\u0142u ze wszystkich kana\u0142\xF3w, w kt\xF3rych go opublikowano - dlatego warto prowadzi\u0107 rejestr publikacji."],bullets:["forma pisemna albo dokumentowa, z mo\u017Cliwo\u015Bci\u0105 odtworzenia tre\u015Bci zgody","wskazanie kana\u0142\xF3w: strona, Facebook, Instagram, materia\u0142y drukowane","okres publikacji i zasady wycofania zgody","osobna zgoda na zdj\u0119cia dokumentuj\u0105ce przebieg leczenia","rejestr, gdzie i kiedy materia\u0142 zosta\u0142 opublikowany"]},{heading:"Opinie pacjent\xF3w",paragraphs:["Pro\u015Bba o opini\u0119 wys\u0142ana pacjentowi po wizycie to komunikacja zwi\u0105zana z wykonan\u0105 us\u0142ug\u0105, ale spos\xF3b jej wys\u0142ania ma znaczenie: SMS z linkiem do wystawienia opinii bywa kwalifikowany jako informacja handlowa, wi\u0119c bezpieczniej jest opiera\u0107 go na zgodzie zebranej przy rejestracji.","Odpowiadaj\u0105c publicznie na opini\u0119, nigdy nie potwierdzaj, \u017Ce autor by\u0142 twoim pacjentem, nie odno\u015B si\u0119 do przebiegu leczenia i nie prostuj fakt\xF3w medycznych w komentarzu. Standardowa odpowied\u017A to podzi\u0119kowanie i zaproszenie do kontaktu bezpo\u015Bredniego. Wyja\u015Bnienia prowadzi si\u0119 poza publiczn\u0105 cz\u0119\u015Bci\u0105."],link:{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Moment pro\u015Bby, jej tre\u015B\u0107 i odpowiadanie na opinie negatywne."}},{heading:"Umowa powierzenia z agencj\u0105 i dostawcami",paragraphs:["Je\u017Celi agencja obs\u0142uguje wiadomo\u015Bci od pacjent\xF3w, prowadzi wysy\u0142k\u0119 SMS albo ma dost\u0119p do systemu rejestracji, przetwarza dane w imieniu plac\xF3wki. Wymaga to umowy powierzenia okre\u015Blaj\u0105cej zakres, cel, kategorie danych, obowi\u0105zki bezpiecze\u0144stwa i zasady usuni\u0119cia danych po zako\u0144czeniu wsp\xF3\u0142pracy.","To samo dotyczy dostawcy hostingu, systemu do wysy\u0142ki SMS i firmy prowadz\u0105cej infolini\u0119. W praktyce warto prowadzi\u0107 prost\u0105 list\u0119 wszystkich podmiot\xF3w maj\u0105cych dost\u0119p do danych - przy kontroli jest to pierwszy dokument, o kt\xF3ry pyta inspektor."]},{heading:"Formularze i piksele reklamowe",paragraphs:['Formularz kontaktowy powinien zbiera\u0107 wy\u0142\u0105cznie dane potrzebne do odpowiedzi i zawiera\u0107 klauzul\u0119 informacyjn\u0105: kto jest administratorem, w jakim celu przetwarza dane, jak d\u0142ugo je trzyma i jakie prawa ma osoba, kt\xF3ra je zostawia. Pole \u201Eopisz sw\xF3j problem zdrowotny" lepiej z formularza usun\u0105\u0107 - zbiera dane o zdrowiu bez potrzeby.',"Piksele Meta i Google zbieraj\u0105 dane o zachowaniu u\u017Cytkownika. Umieszczone na podstronie konkretnej us\u0142ugi medycznej mog\u0105 ujawnia\u0107 zainteresowanie okre\u015Blonym leczeniem. Wymagaj\u0105 zgody na cookies zebranej przed uruchomieniem i ostro\u017Cno\u015Bci przy tym, na kt\xF3rych podstronach je w\u0142\u0105czasz."],bullets:["minimalny zakres p\xF3l w formularzu, bez pyta\u0144 o stan zdrowia","klauzula informacyjna i osobna zgoda na kontakt","baner cookies blokuj\u0105cy skrypty marketingowe do momentu zgody","ostro\u017Cno\u015B\u0107 z pikselami na podstronach us\u0142ug wra\u017Cliwych"]},{heading:"Najcz\u0119stsze b\u0142\u0119dy, kt\xF3re widzimy",paragraphs:["Pierwszy: zdj\u0119cia z poczekalni z rozpoznawalnymi pacjentami w tle, publikowane bez zgody. Drugi: odpowied\u017A na negatywn\u0105 opini\u0119 zawieraj\u0105ca szczeg\xF3\u0142y wizyty, czyli ujawnienie danych o zdrowiu w reakcji na krytyk\u0119. Trzeci: baza numer\xF3w telefon\xF3w zebrana w rejestracji, u\u017Cywana do wysy\u0142ki promocji bez zgody marketingowej.","Czwarty jest cichy i najcz\u0119stszy: brak umowy powierzenia z agencj\u0105, kt\xF3ra od dw\xF3ch lat odpowiada na wiadomo\u015Bci pacjent\xF3w w imieniu plac\xF3wki."]}],faq:[{question:"Czy mog\u0119 wysy\u0142a\u0107 pacjentom SMS-y z promocjami?",answer:"Tylko na podstawie zgody marketingowej zebranej wcze\u015Bniej i osobno od zgody na kontakt w sprawie wizyty. Numer podany przy rejestracji s\u0142u\u017Cy do umawiania i przypominania o wizytach - u\u017Cycie go do wysy\u0142ki ofert bez odr\u0119bnej zgody jest naruszeniem."},{question:"Czy mog\u0119 opublikowa\u0107 podzi\u0119kowanie od pacjenta na stronie?",answer:"Tak, je\u015Bli masz pisemn\u0105 zgod\u0119 na publikacj\u0119 tre\u015Bci i - gdy podpisujesz j\u0105 imieniem lub zdj\u0119ciem - tak\u017Ce na wizerunek i dane. Anonimowa opinia bez element\xF3w pozwalaj\u0105cych zidentyfikowa\u0107 osob\u0119 jest bezpieczniejsza, ale mniej wiarygodna dla czytelnika."},{question:"Czy agencja marketingowa potrzebuje umowy powierzenia?",answer:"Tak, je\u017Celi ma dost\u0119p do danych pacjent\xF3w: obs\u0142uguje wiadomo\u015Bci, prowadzi wysy\u0142k\u0119, pracuje w systemie rejestracji albo administruje serwerem ze zg\u0142oszeniami z formularza. Agencja tworz\u0105ca wy\u0142\u0105cznie grafiki bez dost\u0119pu do danych umowy nie wymaga."},{question:"Czy zdj\u0119cia przed i po s\u0105 dozwolone?",answer:"S\u0105 dozwolone przy pisemnej zgodzie pacjenta obejmuj\u0105cej publikacj\u0119 wizerunku i dokumentacji przebiegu leczenia we wskazanych kana\u0142ach. Zdj\u0119cia musz\u0105 pokazywa\u0107 rzeczywisty efekt - obr\xF3bka zmieniaj\u0105ca wynik wprowadza pacjent\xF3w w b\u0142\u0105d i nara\u017Ca plac\xF3wk\u0119 na zarzut nieuczciwej praktyki."}],sources:[{label:"Rozporz\u0105dzenie 2016/679 (RODO), tekst w j\u0119zyku polskim",url:"https://eur-lex.europa.eu/legal-content/PL/TXT/?uri=CELEX%3A32016R0679",publisher:"EUR-Lex"},{label:"Urz\u0105d Ochrony Danych Osobowych",url:"https://uodo.gov.pl/",publisher:"UODO"}],related:[{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Procedura zbierania opinii bez selekcji i bez nagr\xF3d."},{path:"/uslugi/social-media-dla-klinik",label:"Social media dla klinik",description:"Publikacje i obs\u0142uga wiadomo\u015Bci w granicach ochrony danych."},{path:"/polityka-prywatnosci",label:"Polityka prywatno\u015Bci mediaso",description:"Przyk\u0142ad tego, jak opisujemy przetwarzanie danych u siebie."}]},{slug:"ile-kosztuje-strona-dla-przychodni",title:"Ile kosztuje strona internetowa dla przychodni",h1:"Ile kosztuje strona internetowa dla przychodni",seoTitle:"Ile kosztuje strona internetowa dla przychodni | mediaso",seoDescription:"Rynkowe wide\u0142ki cenowe stron dla przychodni i gabinet\xF3w, z czego sk\u0142ada si\u0119 wycena, koszty utrzymania i miejsca, w kt\xF3rych wykonawcy ukrywaj\u0105 koszty.",datePublished:"2026-08-29",dateModified:"2026-10-25",readingMinutes:7,lead:"Strona internetowa dla przychodni kosztuje w Polsce od oko\u0142o 3 000 z\u0142otych netto za prosty serwis gabinetu do kilkudziesi\u0119ciu tysi\u0119cy za rozbudowany portal plac\xF3wki wieloodzia\u0142owej z w\u0142asnym systemem rezerwacji. Rozpi\u0119to\u015B\u0107 bierze si\u0119 z trzech rzeczy: liczby podstron, kt\xF3re kto\u015B musi zaprojektowa\u0107 i napisa\u0107, sposobu umawiania wizyt oraz tego, czy tre\u015Bci powstaj\u0105 od zera, czy plac\xF3wka dostarcza gotowe. Do ceny wykonania dochodz\u0105 koszty sta\u0142e: domena, hosting i opieka techniczna. Poni\u017Cej rozk\u0142adamy rynkowe wyceny na cz\u0119\u015Bci, \u017Ceby da\u0142o si\u0119 por\xF3wna\u0107 oferty, kt\xF3re na pierwszy rzut oka r\xF3\u017Cni\u0105 si\u0119 o po\u0142ow\u0119.",sections:[{heading:"Trzy poziomy i rynkowe wide\u0142ki",paragraphs:["Poni\u017Csze kwoty to przedzia\u0142y, kt\xF3re wida\u0107 w ofertach polskich wykonawc\xF3w w 2026 roku, nie cennik jednej firmy. Prosta strona gabinetu na gotowym szablonie, do trzech podstron, kosztuje zwykle od 2 500 do 5 000 z\u0142otych netto: strona g\u0142\xF3wna, opis us\u0142ug, cennik, kontakt z map\u0105 i formularz. Wystarcza praktyce jednoosobowej. Termin realizacji to najcz\u0119\u015Bciej 1-2 tygodnie.","Strona z indywidualnym projektem i kilkoma podstronami us\u0142ug to przedzia\u0142 od 5 000 do 10 000 z\u0142otych. Tu pojawia si\u0119 praca, kt\xF3rej nie wida\u0107 w wycenie: struktura podstron pod wyszukiwark\u0119, teksty do ka\u017Cdej us\u0142ugi i akceptacja merytoryczna. Serwis z blogiem i systemem zarz\u0105dzania tre\u015Bci\u0105 mie\u015Bci si\u0119 zwykle mi\u0119dzy 8 000 a 15 000 z\u0142otych.","Powy\u017Cej tego poziomu wchodz\u0105 rezerwacje. Osadzenie gotowego systemu typu Booksy czy Calendly to zwykle kilka tysi\u0119cy z\u0142otych. W\u0142asny system rezerwacji z kalendarzem dost\u0119pno\u015Bci, panelem administratora i p\u0142atno\u015Bciami zaczyna si\u0119 w okolicach kilkunastu tysi\u0119cy, a przy wielu lokalizacjach i integracjach z oprogramowaniem gabinetowym cena powstaje dopiero po specyfikacji."],bullets:["strona gabinetu na szablonie, do 3 podstron: ok. 2 500-5 000 z\u0142 netto, 1-2 tygodnie","strona z indywidualnym projektem: ok. 5 000-10 000 z\u0142 netto, 2-4 tygodnie","serwis z blogiem i CMS: ok. 8 000-15 000 z\u0142 netto, 3-6 tygodni","osadzenie gotowego systemu rezerwacji: kilka tysi\u0119cy z\u0142otych","w\u0142asny system rezerwacji: od kilkunastu tysi\u0119cy z\u0142otych"]},{heading:"Co realnie nap\u0119dza cen\u0119",paragraphs:["Liczba unikalnych uk\u0142ad\xF3w strony, a nie liczba podstron. Dwadzie\u015Bcia podstron us\u0142ug na jednym szablonie to jeden projekt i dwadzie\u015Bcia wype\u0142nie\u0144. Pi\u0119\u0107 podstron, z kt\xF3rych ka\u017Cda wygl\u0105da inaczej, to pi\u0119\u0107 projekt\xF3w.","Spos\xF3b umawiania wizyt jest drugim czynnikiem. Formularz zg\u0142oszenia to kilka godzin pracy. Integracja z systemem gabinetowym przez API to dni albo tygodnie, zale\u017Cnie od jako\u015Bci dokumentacji dostawcy - a bywa, \u017Ce integracja jest niemo\u017Cliwa i trzeba to sprawdzi\u0107 przed podpisaniem umowy.","Trzeci czynnik to tre\u015B\u0107. Napisanie opis\xF3w us\u0142ug medycznych wymaga rozmowy z lekarzem i poprawek po akceptacji. Wykonawca, kt\xF3ry wycenia stron\u0119 bez pytania o to, kto pisze teksty, prawdopodobnie zak\u0142ada, \u017Ce dostarczy je plac\xF3wka."],link:{path:"/wiedza/czym-jest-marketing-medyczny",label:"Czym jest marketing medyczny",description:"Gdzie strona mie\u015Bci si\u0119 w ca\u0142ym bud\u017Cecie plac\xF3wki."}},{heading:"Koszty, kt\xF3re pojawiaj\u0105 si\u0119 po wdro\u017Ceniu",paragraphs:["Domena to kilkadziesi\u0105t z\u0142otych rocznie i zwykle op\u0142aca j\u0105 plac\xF3wka bezpo\u015Brednio. Hosting z certyfikatem SSL, kopiami zapasowymi i monitoringiem dost\u0119pno\u015Bci kosztuje od kilkudziesi\u0119ciu do oko\u0142o dwustu z\u0142otych miesi\u0119cznie, zale\u017Cnie od tego, czy serwis potrzebuje bazy danych.","Opieka techniczna to aktualizacje, kontrola dzia\u0142ania i drobne poprawki. Rynkowo kosztuje od oko\u0142o 200 z\u0142otych miesi\u0119cznie za podstawowy pakiet z godzin\u0105 lub dwiema pracy do ponad tysi\u0105ca z\u0142otych przy kilku godzinach, priorytetowej obs\u0142udze i raporcie. Przy stronie na systemie CMS aktualizacje s\u0105 warunkiem bezpiecze\u0144stwa: nieaktualizowana instalacja zostaje zwykle przej\u0119ta w ci\u0105gu kilku miesi\u0119cy.","Nowe funkcje i wi\u0119ksze zmiany wykonawcy rozliczaj\u0105 najcz\u0119\u015Bciej godzinowo, z estymacj\u0105 przed rozpocz\u0119ciem prac. Pytaj o estymacj\u0119 na pi\u015Bmie, zanim zlecisz zmian\u0119."],bullets:["domena: kilkadziesi\u0105t z\u0142otych rocznie","hosting z SSL, kopiami i monitoringiem: od kilkudziesi\u0119ciu do ok. 200 z\u0142 miesi\u0119cznie","opieka techniczna: od ok. 200 z\u0142 do ponad 1 000 z\u0142 miesi\u0119cznie, zale\u017Cnie od liczby godzin","nowe funkcje i zmiany poza zakresem: rozliczenie godzinowe po estymacji"]},{heading:"Gdzie wyceny bywaj\u0105 nieszczere",paragraphs:["Najcz\u0119stszy zabieg to niska cena wykonania i wysoki abonament z blokad\u0105 wyj\u015Bcia: plac\xF3wka nie dostaje dost\u0119pu do kodu ani do hostingu, wi\u0119c przeniesienie strony do innego wykonawcy oznacza budow\u0119 od zera. Pytanie kontrolne przed podpisaniem umowy brzmi: czy dostaj\u0119 pe\u0142ny dost\u0119p do serwera, domeny i kodu.",'Drugi zabieg to \u201ESEO w pakiecie", kt\xF3re okazuje si\u0119 wpisaniem s\u0142\xF3w kluczowych w tytu\u0142y. Trzeci to teksty generowane hurtowo bez konsultacji medycznej - tanie w produkcji, kosztowne, gdy pacjent znajdzie w opisie zabiegu b\u0142\u0105d.']},{heading:"Jak por\xF3wna\u0107 dwie oferty",paragraphs:["Zestaw je na jednej kartce wed\u0142ug: liczby unikalnych projekt\xF3w, tego kto pisze tre\u015Bci, sposobu umawiania wizyt, w\u0142a\u015Bciciela domeny i hostingu, zakresu opieki po wdro\u017Ceniu i terminu realizacji z kar\u0105 za op\xF3\u017Anienie.","R\xF3\u017Cnica w cenie zwykle mie\u015Bci si\u0119 w dw\xF3ch pozycjach: tre\u015Bci i integracji. Je\u015Bli ta\u0144sza oferta ich nie obejmuje, nie jest ta\u0144sza - przenosi koszt na plac\xF3wk\u0119 i na termin uruchomienia."]}],faq:[{question:"Ile kosztuje strona dla gabinetu lekarskiego?",answer:"Serwis gabinetu z opisem us\u0142ug, cennikiem i formularzem kontaktowym kosztuje na rynku zwykle od 2 500 do 5 000 z\u0142otych netto przy kilku podstronach na gotowym szablonie, a od 5 000 do 10 000 z\u0142otych przy indywidualnym projekcie. Poni\u017Cej tych kwot dostaje si\u0119 najcz\u0119\u015Bciej szablon z podmienionym logo, bez pracy nad struktur\u0105 i tre\u015Bci\u0105."},{question:"Czy warto p\u0142aci\u0107 abonament za stron\u0119?",answer:"Warto, gdy obejmuje aktualizacje, kopie zapasowe, monitoring i realne wsparcie, a plac\xF3wka zachowuje dost\u0119p do domeny, hostingu i kodu. Nie warto, gdy abonament jest form\u0105 blokady i po jego wypowiedzeniu strona przestaje dzia\u0142a\u0107 albo nie da si\u0119 jej przenie\u015B\u0107."},{question:"Ile trwa budowa strony dla przychodni?",answer:"Od 1-2 tygodni przy prostej wizyt\xF3wce do 3-6 tygodni przy stronie z blogiem i systemem zarz\u0105dzania tre\u015Bci\u0105, licz\u0105c od kompletu materia\u0142\xF3w. W\u0142asny system rezerwacji to dodatkowe 5-8 tygodni. Termin wyd\u0142u\u017Ca si\u0119 najcz\u0119\u015Bciej przez oczekiwanie na materia\u0142y plac\xF3wki: zdj\u0119cia zespo\u0142u, zatwierdzony cennik i akceptacj\u0119 opis\xF3w us\u0142ug."}],sources:[{label:"Web Vitals: wska\u017Aniki szybko\u015Bci i stabilno\u015Bci strony",url:"https://web.dev/articles/vitals",publisher:"web.dev, Google"},{label:"Google Search Essentials",url:"https://developers.google.com/search/docs/essentials",publisher:"Google Search Central"}],related:[{path:"/uslugi/strony-internetowe-dla-placowek-medycznych",label:"Strony internetowe dla plac\xF3wek medycznych",description:"Zakres i harmonogram naszej realizacji, wycena po kr\xF3tkiej rozmowie."},{path:"/wiedza/pozycjonowanie-kliniki-krok-po-kroku",label:"Jak samodzielnie wypromowa\u0107 klinik\u0119 w Google",description:"Strona bez widoczno\u015Bci w Google nie zwraca si\u0119 nigdy."},{path:"/kontakt",label:"Kontakt",description:"Opisz zakres, ode\u015Blemy wycen\u0119 z rozbiciem na pozycje."}]},{slug:"jak-zbierac-opinie-pacjentow",title:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",h1:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",seoTitle:"Jak zbiera\u0107 opinie pacjent\xF3w w Google: wz\xF3r pro\u015Bby i zasady | mediaso",seoDescription:"Gotowy wz\xF3r pro\u015Bby o opini\u0119, najlepszy moment wysy\u0142ki i odpowiedzi na negatywne opinie bez \u0142amania RODO. Czego Google zabrania plac\xF3wkom medycznym.",datePublished:"2026-08-29",dateModified:"2026-10-25",readingMinutes:6,lead:"Opinie w Google s\u0105 w ochronie zdrowia jednym z najmocniejszych czynnik\xF3w decyzji: pacjent czyta je przed pierwszym telefonem, a plac\xF3wka z dwudziestoma \u015Bwie\u017Cymi opiniami wygrywa z plac\xF3wk\u0105 z trzema sprzed czterech lat. Zbieranie opinii jest dozwolone i sensowne, ale ma trzy twarde ograniczenia. Nie wolno wybiera\u0107, kogo si\u0119 pyta, na podstawie przewidywanej oceny. Nie wolno oferowa\u0107 niczego w zamian - ani zni\u017Cki, ani drobnego upominku. Nie wolno publicznie potwierdza\u0107, \u017Ce autor opinii by\u0142 pacjentem, bo to ujawnia informacj\u0119 o jego zdrowiu. Reszta to kwestia procedury: kiedy wys\u0142a\u0107 pro\u015Bb\u0119, jak j\u0105 sformu\u0142owa\u0107, kto odpowiada na opinie i w jakim czasie. Poni\u017Cej gotowy proces do wdro\u017Cenia w rejestracji.",sections:[{heading:"Kiedy prosi\u0107 o opini\u0119",paragraphs:["Najlepszy moment to jeden do dw\xF3ch dni po wizycie - pacjent pami\u0119ta wizyt\u0119, a emocje z poczekalni ju\u017C opad\u0142y. Pro\u015Bba tego samego dnia cz\u0119\u015Bciej trafia w rozdra\u017Cnienie po oczekiwaniu, a po tygodniu wizyta jest ju\u017C ma\u0142o istotna.","Przy leczeniu roz\u0142o\u017Conym w czasie, jak ortodoncja czy implanty, sensowniejszy jest moment zako\u0144czenia etapu, nie pierwszej konsultacji. Pacjent ma wtedy co oceni\u0107."]},{heading:"Do kogo kierowa\u0107 pro\u015Bb\u0119",paragraphs:["Do wszystkich pacjent\xF3w z danej grupy, bez wyj\u0105tk\xF3w. Wybieranie tych, kt\xF3rzy wygl\u0105dali na zadowolonych, jest sterowaniem ocen\u0105 i \u0142amie zasady Google, a wykryte ko\u0144czy si\u0119 utrat\u0105 cz\u0119\u015Bci opinii albo zawieszeniem profilu.","Praktycznie oznacza to prost\u0105 regu\u0142\u0119 w rejestracji: pro\u015Bba wychodzi automatycznie do ka\u017Cdego, kto by\u0142 na wizycie danego typu i wyrazi\u0142 zgod\u0119 na kontakt. Bez decyzji cz\u0142owieka o tym, kogo pomin\u0105\u0107."],bullets:["pro\u015Bba do ca\u0142ej grupy pacjent\xF3w, bez selekcji","\u017Cadnych zni\u017Cek, upomink\xF3w ani punkt\xF3w w zamian za opini\u0119","jeden kana\u0142 kontaktu, ustalony i zapisany w procedurze","brak ponagle\u0144 - jedna pro\u015Bba wystarczy"],link:{path:"/wiedza/wizytowka-google-dla-przychodni",label:"Wizyt\xF3wka Google dla przychodni",description:"Profil, w kt\xF3rym te opinie l\u0105duj\u0105 i kt\xF3ry decyduje o pozycji w mapach."}},{heading:"Jak sformu\u0142owa\u0107 pro\u015Bb\u0119",paragraphs:['Kr\xF3tko, z bezpo\u015Brednim linkiem do formularza opinii i bez sugerowania oceny. Zdanie \u201Eb\u0119dzie nam mi\u0142o, je\u015Bli wystawisz pi\u0119\u0107 gwiazdek" jest ju\u017C sterowaniem. Poprawna wersja prosi o opini\u0119, nie o dobr\u0105 opini\u0119.','Wz\xF3r, kt\xF3ry dzia\u0142a: \u201EDzi\u0119kujemy za wizyt\u0119 w [nazwa plac\xF3wki]. Je\u015Bli ma Pani/Pan chwil\u0119, prosimy o opini\u0119 o naszej pracy: [link]. Opinie pomagaj\u0105 nam poprawia\u0107 obs\u0142ug\u0119." Bez emocji, bez nacisku, bez obietnic.']},{heading:"Odpowiadanie na opinie, w tym negatywne",paragraphs:["Odpowiadaj na wszystkie, w ci\u0105gu kilku dni roboczych. Przy opinii pozytywnej wystarczy podzi\u0119kowanie bez odnoszenia si\u0119 do przebiegu leczenia. Przy negatywnej obowi\u0105zuje zasada, kt\xF3ra wygl\u0105da niewygodnie: nie potwierdzasz, \u017Ce autor by\u0142 pacjentem, i nie prostujesz publicznie fakt\xF3w medycznych.","Bezpieczny wz\xF3r: podzi\u0119kowanie za sygna\u0142, informacja, \u017Ce plac\xF3wka traktuje uwagi powa\u017Cnie, i zaproszenie do kontaktu bezpo\u015Bredniego pod wskazany adres lub numer. Wyja\u015Bnienia prowadzisz poza publiczn\u0105 cz\u0119\u015Bci\u0105. Opinie ewidentnie fa\u0142szywe albo obra\u017Aliwe zg\u0142aszasz do platformy, zamiast wdawa\u0107 si\u0119 w sp\xF3r."],bullets:["odpowied\u017A na ka\u017Cd\u0105 opini\u0119 w kilka dni roboczych","brak publicznego potwierdzenia, \u017Ce autor by\u0142 pacjentem","\u017Cadnych szczeg\xF3\u0142\xF3w leczenia w odpowiedzi","zaproszenie do kontaktu bezpo\u015Bredniego zamiast dyskusji pod opini\u0105","zg\u0142oszenie do platformy przy naruszeniu jej zasad"]},{heading:"Co mierzy\u0107",paragraphs:["Trzy liczby wystarcz\u0105: \u015Brednia ocena, liczba nowych opinii w miesi\u0105cu i odsetek opinii z odpowiedzi\u0105. Tempo przyrostu ma dla widoczno\u015Bci wi\u0119ksze znaczenie ni\u017C sama \u015Brednia - profil z opiniami sprzed trzech lat wygl\u0105da na porzucony.","Realny cel dla plac\xF3wki uruchamiaj\u0105cej proces od zera to kilka nowych opinii miesi\u0119cznie. Skok z trzech do pi\u0119\u0107dziesi\u0119ciu w miesi\u0105c jest sygna\u0142em ostrzegawczym dla algorytmu i bywa ko\u0144czony masowym usuni\u0119ciem."]}],faq:[{question:"Czy mo\u017Cna prosi\u0107 pacjent\xF3w o opinie w Google?",answer:"Tak. Google zabrania natomiast oferowania korzy\u015Bci w zamian za opini\u0119 oraz zbierania opinii wy\u0142\u0105cznie od wybranych, zadowolonych pacjent\xF3w. Pro\u015Bba skierowana do wszystkich pacjent\xF3w z danej grupy, bez nagrody, jest zgodna z zasadami."},{question:"Czy plac\xF3wka mo\u017Ce odpowiada\u0107 na negatywne opinie?",answer:"Mo\u017Ce i powinna, ale bez potwierdzania, \u017Ce autor by\u0142 pacjentem, i bez odnoszenia si\u0119 do przebiegu leczenia. Publiczne przywo\u0142anie szczeg\xF3\u0142\xF3w wizyty jest ujawnieniem danych o zdrowiu, nawet je\u015Bli to autor opinii zacz\u0105\u0142 o nich pisa\u0107."},{question:"Czy mo\u017Cna usun\u0105\u0107 niesprawiedliw\u0105 opini\u0119?",answer:"Plac\xF3wka mo\u017Ce zg\u0142osi\u0107 j\u0105 do platformy jako naruszenie zasad - na przyk\u0142ad gdy zawiera dane osobowe, tre\u015Bci obra\u017Aliwe lub dotyczy innej firmy. Google rozpatruje zg\u0142oszenia indywidualnie i nie usuwa opinii tylko dlatego, \u017Ce jest negatywna."},{question:"Ile opinii potrzebuje plac\xF3wka?",answer:"Liczy si\u0119 nie tyle \u0142\u0105czna liczba, co regularny dop\u0142yw. Kilka nowych opinii miesi\u0119cznie utrzymuje profil w rotacji i pokazuje pacjentowi, \u017Ce plac\xF3wka dzia\u0142a. Nag\u0142y skok z kilku do kilkudziesi\u0119ciu w kr\xF3tkim czasie bywa oznaczany jako podejrzany."}],sources:[{label:"Tre\u015Bci zabronione i obj\u0119te ograniczeniami w Mapach Google",url:"https://support.google.com/contributionpolicy/answer/7400114",publisher:"Pomoc Google"},{label:"Opinie w Profilu Firmy w Google",url:"https://support.google.com/business/answer/2622994",publisher:"Pomoc Google"}],related:[{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Opinie s\u0105 jednym z trzech filar\xF3w widoczno\u015Bci w mapach."},{path:"/wiedza/rodo-w-marketingu-placowki-medycznej",label:"RODO w marketingu plac\xF3wki medycznej",description:"Zgody i granice publikowania informacji o pacjentach."},{path:"/wiedza/reklama-swiadczen-zdrowotnych-co-wolno",label:"Reklama \u015Bwiadcze\u0144 zdrowotnych: co wolno",description:"Opinie to jeden z materia\u0142\xF3w, kt\xF3re podlegaj\u0105 zakazowi reklamy \u015Bwiadcze\u0144."}]}];var o=[{slug:"pozycjonowanie-klinik",navLabel:"Pozycjonowanie klinik",h1:"Pozycjonowanie klinik, przychodni i centr\xF3w medycznych",seoTitle:"Pozycjonowanie klinik medycznych i przychodni - SEO dla klinik | mediaso",seoDescription:"Pozycjonowanie klinik, centr\xF3w medycznych, przychodni i gabinet\xF3w lekarskich. Frazy lokalne, podstrony us\u0142ug, wizyt\xF3wka Google i tre\u015Bci zgodne z zakazem reklamy.",schemaName:"Pozycjonowanie klinik i plac\xF3wek medycznych",schemaServiceType:"SEO dla bran\u017Cy medycznej",lead:'Pozycjonowanie kliniki polega na tym, \u017Ceby strona plac\xF3wki pojawia\u0142a si\u0119 w Google wtedy, gdy pacjent szuka konkretnej us\u0142ugi w konkretnym mie\u015Bcie. W praktyce oznacza to trzy rzeczy naraz: osobn\u0105 podstron\u0119 dla ka\u017Cdej us\u0142ugi, kt\xF3r\u0105 plac\xF3wka realnie sprzedaje, uporz\u0105dkowan\u0105 wizyt\xF3wk\u0119 Google spi\u0119t\u0105 z tymi podstronami oraz techniczn\u0105 stron\u0119 serwisu, kt\xF3r\u0105 Google potrafi przeczyta\u0107 i szybko wy\u015Bwietli\u0107 na telefonie. Najwi\u0119kszy ruch w medycynie jest lokalny i bardzo konkretny: \u201Eortodonta Wroc\u0142aw Krzyki", \u201EUSG jamy brzusznej Pozna\u0144", \u201Eendokrynolog prywatnie Gda\u0144sk". Jedna strona z list\u0105 wszystkich us\u0142ug nie wygra \u017Cadnego z tych zapyta\u0144, bo odpowiada na wszystkie po trochu. Prowadzimy pozycjonowanie w modelu: audyt, architektura podstron, tre\u015Bci, wdro\u017Cenie techniczne, comiesi\u0119czne raportowanie pozycji i telefon\xF3w z Google.',sections:[{heading:"Od czego zaczynamy: audyt zamiast obietnic",paragraphs:["Pierwsze dwa tygodnie to praca na danych plac\xF3wki, nie na szablonie. Sprawdzamy, na jakie frazy strona ju\u017C si\u0119 wy\u015Bwietla w Search Console, kt\xF3re podstrony przynosz\u0105 telefony, jak wygl\u0105da wizyt\xF3wka Google w por\xF3wnaniu z trzema najbli\u017Cszymi konkurentami i co blokuje indeksowanie po stronie technicznej.","Z audytu wychodzi lista fraz podzielona na trzy koszyki: zapytania, na kt\xF3rych plac\xF3wka jest blisko pierwszej dziesi\u0105tki i wystarczy je dopchn\u0105\u0107, zapytania wymagaj\u0105ce nowej podstrony oraz zapytania, kt\xF3rych nie warto atakowa\u0107, bo kupuje je sie\u0107 medyczna z bud\u017Cetem niepor\xF3wnywalnym z lokaln\u0105 przychodni\u0105. Ten trzeci koszyk jest r\xF3wnie wa\u017Cny - oszcz\u0119dza miesi\u0105ce pracy."],bullets:["analiza widoczno\u015Bci w Google Search Console i pozycji na frazy us\u0142ugowe","por\xF3wnanie wizyt\xF3wki Google z konkurencj\u0105 w promieniu obs\u0142ugiwanego obszaru","audyt techniczny: indeksowanie, szybko\u015B\u0107 na telefonie, dane strukturalne","mapa fraz z podzia\u0142em na us\u0142ugi, lokalizacje i pytania pacjent\xF3w"]},{heading:"Architektura podstron: jedna us\u0142uga, jeden adres",paragraphs:['Google przypisuje wynik do adresu URL, nie do domeny. Je\u017Celi implantologia, ortodoncja i higienizacja mieszkaj\u0105 na jednej podstronie \u201EUs\u0142ugi", strona konkuruje sama ze sob\u0105 i przegrywa z gabinetem, kt\xF3ry ma trzy osobne adresy. Rozbijamy ofert\u0119 na podstrony i pilnujemy, \u017Ceby ka\u017Cda odpowiada\u0142a na inne pytanie pacjenta.',"Ka\u017Cda podstrona us\u0142ugi dostaje opis przebiegu wizyty, przygotowanie pacjenta, przeciwwskazania, orientacyjny czas i cen\u0119 oraz sekcj\u0119 pyta\u0144. Przy plac\xF3wkach wieloodzia\u0142owych dok\u0142adamy warstw\u0119 lokalizacji: osobny adres dla ka\u017Cdego oddzia\u0142u z godzinami, parkingiem, dojazdem i zespo\u0142em. Struktura linkowania trzyma to razem - z us\u0142ugi do oddzia\u0142u i z oddzia\u0142u do us\u0142ug, kt\xF3re w nim realnie dzia\u0142aj\u0105."],bullets:["osobna podstrona dla ka\u017Cdej us\u0142ugi kupowanej przez pacjenta","strony oddzia\u0142\xF3w dla plac\xF3wek z kilkoma adresami","linkowanie wewn\u0119trzne mi\u0119dzy us\u0142ug\u0105, oddzia\u0142em i specjalist\u0105","dane strukturalne MedicalBusiness i FAQ na podstronach us\u0142ug"]},{heading:"Tre\u015B\u0107, kt\xF3ra przechodzi przez wymagania bran\u017Cy medycznej",paragraphs:["Reklama i prezentacja us\u0142ug medycznych podlega ograniczeniom, kt\xF3rych nie ma w innych bran\u017Cach - obowi\u0105zuj\u0105 mi\u0119dzy innymi przepisy o zawodach lekarza i lekarza dentysty oraz zasady kodeksu etyki lekarskiej dotycz\u0105ce tre\u015Bci reklamowych. Nie obiecujemy w tekstach wynik\xF3w leczenia, nie budujemy przekazu na por\xF3wnaniach z konkretnymi konkurentami i nie publikujemy zdj\u0119\u0107 pacjent\xF3w bez pisemnej zgody.","Tre\u015Bci opiniuje osoba merytoryczna po stronie plac\xF3wki. To nie jest formalno\u015B\u0107: opis zabiegu napisany przez copywritera bez konsultacji z lekarzem prowadz\u0105cym potrafi zawiera\u0107 b\u0142\u0105d, kt\xF3ry kosztuje wiarygodno\u015B\u0107 u pacjenta i u Google. Publikujemy dopiero po akceptacji."]},{heading:"Pozycjonowanie lokalne plac\xF3wki medycznej",paragraphs:['Pacjent rzadko wpisuje sam\u0105 nazw\u0119 specjalizacji. Wpisuje \u201Eginekolog Mokot\xF3w", \u201Erezonans magnetyczny \u0141\xF3d\u017A prywatnie" albo \u201Estomatolog blisko mnie". Google odpowiada na takie zapytania dwoma blokami naraz: map\u0105 z trzema plac\xF3wkami i zwyk\u0142ymi wynikami pod ni\u0105. Pozycjonowanie lokalne obs\u0142uguje oba: wizyt\xF3wk\u0119 Google z w\u0142a\u015Bciw\u0105 kategori\u0105 i opiniami oraz podstrony us\u0142ug z nazw\u0105 miasta i dzielnicy w tre\u015Bci, tytule i danych strukturalnych.',"Przy centrum medycznym z kilkoma poradniami uk\u0142adamy frazy w siatk\u0119: specjalizacja razem z miastem, badanie razem z miastem, a przy du\u017Cych miastach dodatkowo dzielnica. Ka\u017Cde pole siatki dostaje jeden adres na stronie, a wizyt\xF3wka linkuje do podstrony, kt\xF3rej zapytanie dotyczy, zamiast do strony g\u0142\xF3wnej."],bullets:['frazy \u201Eus\u0142uga + miasto" i \u201Eus\u0142uga + dzielnica" przypisane do konkretnych podstron',"sp\xF3jna nazwa, adres i telefon na stronie, w wizyt\xF3wce i w katalogach medycznych","dane strukturalne MedicalClinic lub Physician z adresem i godzinami","linki z wizyt\xF3wki Google do podstron us\u0142ug, nie tylko do strony g\u0142\xF3wnej"],link:{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Druga po\u0142owa pozycjonowania lokalnego: mapy, kategorie i opinie."}},{heading:"SEO dla klinik stomatologicznych, estetycznych i dla lekarzy",paragraphs:["Ka\u017Cdy typ plac\xF3wki ma inny rozk\u0142ad zapyta\u0144. Klinika stomatologiczna zarabia na implantach, ortodoncji i protetyce, wi\u0119c to te trzy us\u0142ugi dostaj\u0105 najbardziej rozbudowane podstrony z przebiegiem leczenia, etapami i pytaniami o b\xF3l i czas gojenia. Klinika medycyny estetycznej i chirurgii plastycznej konkuruje na frazach zabiegowych, gdzie tre\u015B\u0107 musi omija\u0107 obietnic\u0119 efektu i zdj\u0119cia przed i po bez zgody - tu ograniczenia reklamy s\u0105 najcz\u0119\u015Bciej \u0142amane przez konkurencj\u0119 i najcz\u0119\u015Bciej zg\u0142aszane.","Przy pozycjonowaniu lekarza pracujemy te\u017C na nazwisku. Pacjent, kt\xF3ry dosta\u0142 polecenie, wpisuje imi\u0119 i nazwisko specjalisty, a w wynikach widzi zwykle profil w katalogu lekarzy zamiast strony samego lekarza. Osobna podstrona specjalisty z zakresem przyj\u0119\u0107, kwalifikacjami i miejscami przyj\u0119\u0107, spi\u0119ta danymi strukturalnymi Physician, odzyskuje ten ruch. Fizjoterapia, diagnostyka obrazowa i laboratoria maj\u0105 w\u0142asne wzorce zapyta\u0144, g\u0142\xF3wnie cenowe i lokalne, i dla nich budujemy osobn\u0105 map\u0119 fraz."],bullets:["stomatologia: implanty, ortodoncja, protetyka, leczenie kana\u0142owe pod mikroskopem","medycyna estetyczna i chirurgia plastyczna: frazy zabiegowe bez obietnic efektu","lekarze specjali\u015Bci: podstrona lekarza i widoczno\u015B\u0107 na imi\u0119 i nazwisko","diagnostyka, laboratoria, fizjoterapia: zapytania o cen\u0119, przygotowanie i dost\u0119pno\u015B\u0107"]},{heading:"Jak wyceniamy pozycjonowanie",paragraphs:["Nie sprzedajemy pakiet\xF3w z g\xF3ry. Koszt pozycjonowania kliniki zale\u017Cy od trzech rzeczy: liczby us\u0142ug, kt\xF3re maj\u0105 si\u0119 wy\u015Bwietla\u0107 w Google, liczby miast i oddzia\u0142\xF3w oraz od tego, ile pracy wymaga obecna strona. Przychodnia w mie\u015Bcie powiatowym z pi\u0119cioma us\u0142ugami i centrum medyczne z trzema oddzia\u0142ami w Warszawie to dwa r\xF3\u017Cne projekty, a wsp\xF3lny cennik zawy\u017Cy\u0142by cen\u0119 pierwszemu albo zani\u017Cy\u0142 zakres drugiemu.","Wycena powstaje po bezp\u0142atnej 30-minutowej konsultacji i kr\xF3tkim przegl\u0105dzie strony oraz wizyt\xF3wki. Dostajesz zakres prac rozpisany na miesi\u0105ce, list\u0119 fraz, od kt\xF3rych zaczynamy, i sta\u0142\u0105 kwot\u0119 za uzgodniony zakres."]},{heading:"Czego realnie oczekiwa\u0107 i kiedy",paragraphs:["SEO nie dzia\u0142a w tydzie\u0144. Pierwsze ruchy pozycji na frazy o niskiej konkurencji wida\u0107 zwykle po 6-10 tygodniach od wdro\u017Cenia zmian technicznych i publikacji podstron. Frazy og\xF3lne w du\u017Cym mie\u015Bcie to horyzont kilku kwarta\u0142\xF3w i nie ma sensu obiecywa\u0107 inaczej.","Podstawowa optymalizacja nie jest gwarancj\u0105 pozycji, ruchu ani liczby zapyta\u0144 - wynik zale\u017Cy te\u017C od konkurencji, tre\u015Bci, bud\u017Cetu i historii domeny. To, co mo\u017Cemy obieca\u0107, to wykonana praca i jej rozliczenie: pozycje na uzgodnionej li\u015Bcie fraz, wej\u015Bcia z wyszukiwarki oraz telefony i klikni\u0119cia w tras\u0119 z wizyt\xF3wki Google."]}],faq:[{question:"Ile trwa pozycjonowanie kliniki, zanim wida\u0107 efekty?",answer:"Pierwsze wzrosty pozycji na frazy lokalne i mniej konkurencyjne pojawiaj\u0105 si\u0119 zwykle po 6-10 tygodniach od wdro\u017Cenia zmian. Frazy og\xF3lne w du\u017Cych miastach wymagaj\u0105 zwykle 6-12 miesi\u0119cy systematycznej pracy. Ka\u017Cdy, kto obiecuje pierwsze miejsce w miesi\u0105c, sprzedaje co\u015B innego ni\u017C SEO."},{question:"Czy pozycjonowanie kliniki jest zgodne z zakazem reklamy us\u0142ug medycznych?",answer:"Tak, o ile tre\u015Bci trzymaj\u0105 si\u0119 ogranicze\u0144 bran\u017Cowych. Publikujemy rzetelne informacje o zakresie us\u0142ug, przebiegu wizyty i cenach, nie obiecujemy skutk\xF3w leczenia i nie budujemy przekazu na por\xF3wnaniach z konkretnymi plac\xF3wkami. Ka\u017Cdy tekst medyczny akceptuje osoba merytoryczna po stronie plac\xF3wki."},{question:"Ile kosztuje pozycjonowanie kliniki?",answer:"Koszt zale\u017Cy od liczby us\u0142ug, kt\xF3re maj\u0105 si\u0119 wy\u015Bwietla\u0107 w Google, liczby miast i oddzia\u0142\xF3w oraz stanu obecnej strony. Wycen\u0119 przygotowujemy po bezp\u0142atnej 30-minutowej konsultacji: zakres prac rozpisany na miesi\u0105ce i sta\u0142a kwota za uzgodniony zakres, bez dop\u0142at za wyniki."},{question:"Czym r\xF3\u017Cni si\u0119 pozycjonowanie lekarza od pozycjonowania kliniki?",answer:'Klinika walczy o frazy us\u0142ugowe z miastem, na przyk\u0142ad \u201Eortopeda Krak\xF3w". Lekarz dodatkowo o w\u0142asne imi\u0119 i nazwisko, bo polecony pacjent szuka konkretnej osoby. Lekarz potrzebuje wi\u0119c podstrony z kwalifikacjami, zakresem przyj\u0119\u0107 i adresami gabinet\xF3w, danych strukturalnych Physician i sp\xF3jnego wpisu w katalogach lekarzy.'},{question:"Dlaczego pozycjonowanie plac\xF3wki medycznej warto zleci\u0107 agencji z bran\u017Cy?",answer:"Bo tekst, kt\xF3ry dobrze sprzedaje w innej bran\u017Cy, w medycynie mo\u017Ce by\u0107 wykroczeniem z art. 147a Kodeksu wykrocze\u0144. Agencja pracuj\u0105ca wy\u0142\u0105cznie z plac\xF3wkami medycznymi zna ograniczenia reklamy \u015Bwiadcze\u0144 zdrowotnych, zasady publikowania danych pacjent\xF3w i wzorce zapyta\u0144 w poszczeg\xF3lnych specjalizacjach, wi\u0119c nie traci miesi\u0119cy na nauk\u0119 na koszt klienta."},{question:"Czy potrzebuj\u0119 nowej strony, \u017Ceby zacz\u0105\u0107 pozycjonowanie?",answer:"Nie zawsze. Je\u017Celi obecna strona jest indeksowana, dzia\u0142a na telefonie i da si\u0119 do niej dopisywa\u0107 podstrony, pracujemy na niej. Now\u0105 stron\u0119 rekomendujemy, gdy serwis nie ma systemu zarz\u0105dzania tre\u015Bci\u0105, \u0142aduje si\u0119 kilka sekund albo jest zbudowany tak, \u017Ce Google nie widzi jego tre\u015Bci."},{question:"Co z plac\xF3wk\u0105, kt\xF3ra ma kilka oddzia\u0142\xF3w?",answer:"Ka\u017Cdy oddzia\u0142 dostaje w\u0142asn\u0105 podstron\u0119 z adresem, godzinami, zespo\u0142em i list\u0105 us\u0142ug realizowanych na miejscu, a tak\u017Ce osobn\u0105 wizyt\xF3wk\u0119 Google. Bez tego oddzia\u0142y konkuruj\u0105 ze sob\u0105 w wynikach lokalnych i \u017Caden nie wychodzi wysoko."}],related:[{path:"/uslugi/strony-internetowe-dla-placowek-medycznych",label:"Strony internetowe dla plac\xF3wek medycznych",description:"Podstrony us\u0142ug i lokalizacji, kt\xF3re da si\u0119 pozycjonowa\u0107."},{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Lokalne wyniki i mapy - druga po\u0142owa widoczno\u015Bci w Google."},{path:"/wiedza/pozycjonowanie-kliniki-krok-po-kroku",label:"Jak samodzielnie wypromowa\u0107 klinik\u0119 w Google",description:"Kolejno\u015B\u0107 dzia\u0142a\u0144 opisana tak, \u017Ceby da\u0142o si\u0119 j\u0105 zrobi\u0107 samodzielnie."}]},{slug:"strony-internetowe-dla-placowek-medycznych",navLabel:"Strony internetowe",h1:"Strony internetowe dla plac\xF3wek medycznych",seoTitle:"Strony internetowe dla plac\xF3wek medycznych, przychodni i klinik | mediaso",seoDescription:"Projektujemy strony dla przychodni, klinik i gabinet\xF3w lekarskich: podstrony us\u0142ug pod Google, rezerwacja wizyt online, panel CMS, formularze zgodne z RODO.",schemaName:"Strony internetowe dla plac\xF3wek medycznych",schemaServiceType:"Tworzenie stron internetowych",lead:'Strona plac\xF3wki medycznej ma do wykonania trzy zadania i wszystko poza nimi jest dodatkiem. Ma pozwoli\u0107 pacjentowi um\xF3wi\u0107 wizyt\u0119 w kilka sekund, odpowiedzie\u0107 na pytania, kt\xF3re w innym wypadku trafi\u0142yby do rejestracji, i pokaza\u0107 si\u0119 w Google wtedy, gdy kto\u015B szuka konkretnej us\u0142ugi w okolicy. Wi\u0119kszo\u015B\u0107 stron przychodni przegrywa na pierwszym punkcie: numer telefonu jest w stopce, formularz ma dziewi\u0119\u0107 p\xF3l, a godziny otwarcia le\u017C\u0105 w PDF-ie. Budujemy strony wok\xF3\u0142 \u015Bcie\u017Cki pacjenta, nie wok\xF3\u0142 struktury organizacyjnej plac\xF3wki - bo pacjent nie szuka \u201Edzia\u0142u diagnostyki obrazowej", tylko USG kolana na przysz\u0142y tydzie\u0144. Do tego dochodz\u0105 rzeczy niewidoczne: szybko\u015B\u0107 \u0142adowania na telefonie w s\u0142abym zasi\u0119gu, dost\u0119pno\u015B\u0107 dla os\xF3b starszych i formularze zgodne z RODO.',sections:[{heading:"Co ma by\u0107 na stronie przychodni",paragraphs:["Zestaw obowi\u0105zkowy jest kr\xF3tki i prawie zawsze niekompletny w istniej\u0105cych serwisach. Telefon widoczny bez przewijania i klikalny na telefonie. Godziny przyj\u0119\u0107 jako tekst, nie obrazek. Adres z map\u0105 i informacj\u0105 o parkingu. Cennik albo przynajmniej przedzia\u0142y cenowe. Lista specjalist\xF3w z tym, co realnie przyjmuj\u0105.","Dalej idzie warstwa, kt\xF3ra zdejmuje prac\u0119 z rejestracji: przygotowanie do bada\u0144, wymagane dokumenty, zasady odwo\u0142ywania wizyt, informacja o teleporadach. Ka\u017Cde z tych pyta\u0144 zadawane jest przez telefon kilkana\u015Bcie razy dziennie w \u015Bredniej przychodni."],bullets:["klikalny telefon i przycisk um\xF3wienia wizyty na ka\u017Cdym ekranie","osobna podstrona ka\u017Cdej us\u0142ugi z cen\u0105 i przebiegiem wizyty","strony oddzia\u0142\xF3w i specjalist\xF3w przy plac\xF3wkach wieloosobowych","przygotowanie do bada\u0144 i dokumenty do pobrania","formularz kontaktowy z klauzul\u0105 RODO i zgod\u0105 na kontakt"]},{heading:"Umawianie wizyt: integracja albo prosty formularz",paragraphs:["Je\u017Celi plac\xF3wka pracuje na systemie gabinetowym z modu\u0142em e-rejestracji, spinamy stron\u0119 z tym systemem i nie budujemy drugiego, konkurencyjnego kalendarza. Podw\xF3jny grafik to gwarancja podw\xF3jnej rezerwacji tego samego terminu.","Gdy integracja nie wchodzi w gr\u0119, robimy formularz zg\u0142oszenia wizyty: us\u0142uga, preferowany termin, dane kontaktowe i zgoda na kontakt. Zg\u0142oszenie idzie mailem do rejestracji, a pacjent dostaje jasn\u0105 informacj\u0119, \u017Ce to pro\u015Bba o kontakt, nie potwierdzona rezerwacja. Uczciwy komunikat oszcz\u0119dza reklamacji."]},{heading:"Technologia i utrzymanie",paragraphs:["Strony budujemy jako serwisy statyczne albo na sprawdzonym systemie CMS, zale\u017Cnie od tego, kto i jak cz\u0119sto b\u0119dzie aktualizowa\u0142 tre\u015B\u0107. Plac\xF3wka dostaje dost\u0119p do edycji cennika, godzin i aktualno\u015Bci bez dzwonienia do agencji.","Po\u0142\u0105czenie idzie po HTTPS, a formularze zapisuj\u0105 tylko te dane, kt\xF3re s\u0105 potrzebne do odpowiedzi. Kopie zapasowe i monitoring dost\u0119pno\u015Bci wchodz\u0105 w hosting, aktualizacje oprogramowania w pakiet opieki technicznej. Po op\u0142aceniu ca\u0142o\u015Bci wynagrodzenia plac\xF3wka dostaje uzgodnione w umowie prawa i dost\u0119py do projektu."],bullets:["panel do samodzielnej edycji tre\u015Bci, cennika i godzin","certyfikat SSL, kopie zapasowe i monitoring dost\u0119pno\u015Bci w ramach hostingu","wynik Core Web Vitals mierzony po wdro\u017Ceniu, nie deklarowany","opieka techniczna z aktualizacjami i monitoringiem dost\u0119pno\u015Bci"]},{heading:"Rezerwacja wizyt i p\u0142atno\u015Bci online",paragraphs:["Je\u017Celi plac\xF3wka korzysta z gotowego systemu rezerwacji, osadzamy go na stronie: konfiguracja wid\u017Cetu, typy wizyt, powiadomienia i testy na telefonie. Abonament samego systemu plac\xF3wka op\u0142aca bezpo\u015Brednio u dostawcy.","Gdy gotowe narz\u0119dzie nie wystarcza, budujemy dedykowany system rezerwacji: publiczny kalendarz dost\u0119pno\u015Bci, grafik lekarzy i gabinet\xF3w, panel administratora, potwierdzenia e-mail i przedp\u0142aty za wizyty komercyjne przez Przelewy24, PayU albo Stripe. Przy wielu lokalizacjach najpierw powstaje specyfikacja i harmonogram, dopiero potem wycena."]},{heading:"Jak wygl\u0105da realizacja i ile trwa",paragraphs:["Praca idzie w czterech etapach: rozmowa o \u015Bcie\u017Cce pacjenta i us\u0142ugach, kt\xF3re maj\u0105 przynosi\u0107 wizyty, projekt uk\u0142adu strony, tre\u015Bci z akceptacj\u0105 merytoryczn\u0105 po stronie plac\xF3wki i wdro\u017Cenie z pomiarem szybko\u015Bci na telefonie. Prosta strona gabinetu powstaje w 1-2 tygodnie, serwis przychodni z podstronami us\u0142ug w 2-4 tygodnie, a strona z blogiem i systemem zarz\u0105dzania tre\u015Bci\u0105 w 3-6 tygodni, licz\u0105c od kompletu materia\u0142\xF3w.","Wycen\u0119 przygotowujemy po kr\xF3tkiej rozmowie, bo koszt zale\u017Cy od liczby podstron, sposobu umawiania wizyt i tego, kto pisze tre\u015Bci. Dostajesz zakres z liczb\u0105 podstron i rund poprawek zapisan\u0105 w umowie oraz sta\u0142\u0105 kwot\u0119 za ten zakres. Po wdro\u017Ceniu stron\u0119 utrzymujemy w ramach hostingu i opieki technicznej: aktualizacje, kopie zapasowe, monitoring i drobne poprawki. Przez 30 dni od publikacji bezp\u0142atnie usuwamy b\u0142\u0119dy niezgodne z uzgodnionym zakresem."],bullets:['sta\u0142a kwota za zakres zapisany w umowie, bez dop\u0142at za \u201Edrobne zmiany" w trakcie',"domena, hosting i kod strony zostaj\u0105 u plac\xF3wki","pomiar Core Web Vitals po wdro\u017Ceniu, nie deklaracja w ofercie"],link:{path:"/wiedza/ile-kosztuje-strona-dla-przychodni",label:"Ile kosztuje strona internetowa dla przychodni",description:"Z czego sk\u0142ada si\u0119 wycena i jak por\xF3wna\u0107 dwie oferty."}}],faq:[{question:"Ile kosztuje strona internetowa dla przychodni?",answer:"Koszt zale\u017Cy od liczby podstron, tego, czy projekt jest indywidualny, sposobu umawiania wizyt i tego, kto przygotowuje tre\u015Bci. Wycen\u0119 przygotowujemy po bezp\u0142atnej rozmowie i podajemy j\u0105 jako sta\u0142\u0105 kwot\u0119 za zakres zapisany w umowie. Do koszt\xF3w sta\u0142ych dochodz\u0105 domena, hosting i opcjonalna opieka techniczna."},{question:"Ile trwa wykonanie strony dla plac\xF3wki medycznej?",answer:"Prosta strona gabinetu 1-2 tygodnie, serwis przychodni z podstronami us\u0142ug 2-4 tygodnie, strona z blogiem i CMS 3-6 tygodni - licz\u0105c od otrzymania kompletu materia\u0142\xF3w. Termin przesuwa si\u0119 najcz\u0119\u015Bciej z powodu materia\u0142\xF3w po stronie plac\xF3wki: zdj\u0119\u0107 zespo\u0142u, zatwierdzonego cennika i opis\xF3w us\u0142ug wymagaj\u0105cych akceptacji merytorycznej."},{question:"Czy strona b\u0119dzie zgodna z RODO?",answer:"Formularze zbieraj\u0105 tylko dane potrzebne do odpowiedzi, zawieraj\u0105 klauzul\u0119 informacyjn\u0105 i osobn\u0105 zgod\u0119 na kontakt, a dane trafiaj\u0105 na serwer w Unii Europejskiej. Plac\xF3wka dostaje te\u017C polityk\u0119 prywatno\u015Bci dopasowan\u0105 do tego, co strona faktycznie zbiera, a nie szablon z internetu."},{question:"Czy mog\u0119 sam edytowa\u0107 tre\u015Bci?",answer:"Tak. Cennik, godziny przyj\u0119\u0107, sk\u0142ad zespo\u0142u i aktualno\u015Bci edytuje si\u0119 z panelu bez znajomo\u015Bci kodu. Zmiany w strukturze strony i nowe podstrony us\u0142ug robimy w ramach opieki albo na zlecenie."}],related:[{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie klinik",description:"Strona bez widoczno\u015Bci w Google nie pozyskuje pacjent\xF3w."},{path:"/wiedza/ile-kosztuje-strona-dla-przychodni",label:"Ile kosztuje strona internetowa dla przychodni",description:"Z czego sk\u0142ada si\u0119 wycena i gdzie firmy ukrywaj\u0105 koszty."}]},{slug:"social-media-dla-klinik",navLabel:"Social media",h1:"Prowadzenie social medi\xF3w dla klinik, gabinet\xF3w i lekarzy",seoTitle:"Social media dla lekarzy, klinik i gabinet\xF3w - prowadzenie profili | mediaso",seoDescription:"Prowadzimy Facebooka, Instagrama i TikToka lekarzy, stomatolog\xF3w, fizjoterapeut\xF3w i klinik: plan tre\u015Bci, grafiki, rolki, obs\u0142uga wiadomo\u015Bci i kampanie Meta Ads.",schemaName:"Prowadzenie social media plac\xF3wek medycznych",schemaServiceType:"Zarz\u0105dzanie mediami spo\u0142eczno\u015Bciowymi",lead:"Profil kliniki na Facebooku i Instagramie pe\u0142ni rol\u0119, o kt\xF3rej \u0142atwo zapomnie\u0107: pacjent, kt\xF3ry us\u0142ysza\u0142 nazw\u0119 plac\xF3wki od znajomego, sprawdza j\u0105 tam, zanim zadzwoni. Widzi wtedy albo pracuj\u0105c\u0105 plac\xF3wk\u0119 z aktualnymi informacjami i odpowiedziami na wiadomo\u015Bci, albo profil z ostatnim postem sprzed roku. To rozstrzyga wi\u0119cej decyzji ni\u017C jakakolwiek kampania. Prowadzenie social medi\xF3w plac\xF3wki medycznej sprowadza si\u0119 wi\u0119c najpierw do regularno\u015Bci i obs\u0142ugi wiadomo\u015Bci, a dopiero potem do zasi\u0119g\xF3w. Dochodzi do tego ograniczenie, kt\xF3rego nie ma w innych bran\u017Cach: nie wolno publikowa\u0107 wizerunku ani danych pacjenta bez zgody, a tre\u015B\u0107 nie mo\u017Ce obiecywa\u0107 efektu leczenia. Pracujemy w rytmie miesi\u0119cznym, na planie tre\u015Bci zatwierdzanym z wyprzedzeniem.",sections:[{heading:"Co publikujemy zamiast cytat\xF3w o zdrowiu",paragraphs:["Tre\u015Bci, kt\xF3re w plac\xF3wkach medycznych realnie generuj\u0105 kontakt, s\u0105 konkretne: nowy sprz\u0119t i co dzi\u0119ki niemu mo\u017Cna zbada\u0107, nowy specjalista z zakresem przyj\u0119\u0107, wolne terminy w tym tygodniu, przygotowanie do konkretnego badania, odpowied\u017A na pytanie, kt\xF3re rejestracja s\u0142yszy codziennie.","Post z og\xF3ln\u0105 grafik\u0105 o dbaniu o zdrowie nie przynosi nic poza wype\u0142nieniem kalendarza. Plan tre\u015Bci uk\u0142adamy z zespo\u0142em plac\xF3wki, bo to rejestracja i lekarze wiedz\u0105, o co pacjenci pytaj\u0105 najcz\u0119\u015Bciej."],bullets:["zapowiedzi wolnych termin\xF3w i nowych us\u0142ug","przedstawienie specjalist\xF3w: zakres przyj\u0119\u0107, do\u015Bwiadczenie, j\u0119zyki","instrukcje przygotowania do bada\u0144 w formie kr\xF3tkiego wideo","odpowiedzi na powtarzalne pytania z rejestracji","komunikaty organizacyjne: dni wolne, zmiany godzin, nowy adres"]},{heading:"Profil lekarza a profil plac\xF3wki",paragraphs:["Lekarz prowadz\u0105cy w\u0142asn\u0105 praktyk\u0119 potrzebuje czego\u015B innego ni\u017C przychodnia z sze\u015Bcioma poradniami. Profil plac\xF3wki komunikuje dost\u0119pno\u015B\u0107, zakres us\u0142ug i organizacj\u0119. Profil lekarza sprzedaje kompetencj\u0119 konkretnej osoby, wi\u0119c tre\u015B\u0107 stoi na tym, co ten specjalista realnie robi: jakie przypadki prowadzi, na jakim sprz\u0119cie pracuje, na jakich konferencjach bywa i co z tego wynika dla pacjenta.","Prowadzimy oba warianty, a przy lekarzu zatrudnionym w kilku miejscach ustalamy na starcie, co nale\u017Cy do jego marki osobistej, a co do marki plac\xF3wki. Bez tego rozdzia\u0142u pojawia si\u0119 problem przy zmianie pracy: profil zbudowany wok\xF3\u0142 adresu przychodni traci sens, gdy lekarz zaczyna przyjmowa\u0107 gdzie indziej.","Jedno ograniczenie dotyczy obu przypadk\xF3w tak samo. Lekarz wyst\u0119puj\u0105cy we w\u0142asnym imieniu podlega zasadom kodeksu etyki lekarskiej co do tre\u015Bci reklamowych, wi\u0119c materia\u0142 opiera si\u0119 na informacji o zakresie przyj\u0119\u0107 i przebiegu leczenia, nie na obietnicy wyniku."],bullets:["profil lekarza: marka osobista, zakres przyj\u0119\u0107, do\u015Bwiadczenie, wyst\u0105pienia","profil plac\xF3wki: dost\u0119pno\u015B\u0107 termin\xF3w, organizacja, zesp\xF3\u0142, us\u0142ugi","rozdzia\u0142 tre\u015Bci przy lekarzu przyjmuj\u0105cym w kilku miejscach","wideo z lekarzem jako materia\u0142, kt\xF3rego nie skopiuje \u017Cadna konkurencja"],link:{path:"/wiedza/social-media-dla-lekarzy",label:"Social media dla lekarzy: co publikowa\u0107 i czego nie wolno",description:"Tematy post\xF3w w poszczeg\xF3lnych specjalizacjach i granice Kodeksu Etyki Lekarskiej."}},{heading:"Social media dla stomatolog\xF3w i gabinet\xF3w stomatologicznych",paragraphs:["Stomatologia ma w social mediach przewag\u0119, kt\xF3rej nie ma wi\u0119kszo\u015B\u0107 specjalizacji: efekt pracy wida\u0107, a pacjenci boj\u0105 si\u0119 wizyty bardziej ni\u017C w innych gabinetach. Najlepiej dzia\u0142aj\u0105 wi\u0119c tre\u015Bci, kt\xF3re zdejmuj\u0105 strach: jak wygl\u0105da pierwsza wizyta, co czuje pacjent przy znieczuleniu, ile trwa leczenie kana\u0142owe pod mikroskopem, jak przebiega wizyta adaptacyjna u dziecka.","Granica przebiega przy zdj\u0119ciach przed i po. Pokazane jako dow\xF3d skuteczno\u015Bci s\u0105 traktowane jak reklama \u015Bwiadcze\u0144, a do tego wymagaj\u0105 pisemnej zgody pacjenta. Zamiast metamorfoz publikujemy sprz\u0119t, etapy leczenia na modelach, zesp\xF3\u0142 przy pracy i odpowiedzi lekarza na pytania pacjent\xF3w."],bullets:["pierwsza wizyta i znieczulenie: tre\u015Bci dla pacjent\xF3w z l\u0119kiem przed dentyst\u0105","implanty, ortodoncja i leczenie kana\u0142owe wyja\u015Bnione na modelach i grafikach","stomatologia dzieci\u0119ca: wizyta adaptacyjna, lakowanie, profilaktyka","zesp\xF3\u0142, asystentki i higienistki jako twarze gabinetu"]},{heading:"Fizjoterapeuci, psycholodzy i gabinety specjalistyczne",paragraphs:["Gabinet fizjoterapii, psychologa, dietetyka czy logopedy prowadzi zwykle jedna albo dwie osoby, wi\u0119c profil gabinetu jest w praktyce profilem specjalisty. Pacjent wybiera cz\u0142owieka, z kt\xF3rym b\u0119dzie pracowa\u0142 przez kilka tygodni, i chce go zobaczy\u0107, zanim zadzwoni. Najlepiej pracuje kr\xF3tkie wideo: \u0107wiczenie pokazane przez fizjoterapeut\u0119, odpowied\u017A na pytanie z gabinetu, przebieg pierwszej wizyty.","Przy ma\u0142ym gabinecie liczy si\u0119 te\u017C czas w\u0142a\u015Bciciela. Ustalamy jedn\u0105 sesj\u0119 nagraniow\u0105 w miesi\u0105cu, z kt\xF3rej powstaje materia\u0142 na ca\u0142y miesi\u0105c publikacji, a reszt\u0119 - monta\u017C, opisy, harmonogram i odpowiedzi na komentarze - bierzemy na siebie."]},{heading:"Obs\u0142uga wiadomo\u015Bci i komentarzy",paragraphs:["Wiadomo\u015Bci na Messengerze i Instagramie to dzi\u015B ta sama kolejka co telefon do rejestracji, tylko bez sygna\u0142u zaj\u0119to\u015Bci. Ustalamy z plac\xF3wk\u0105, na co odpowiadamy sami, a co przekazujemy do rejestracji - i w jakim czasie.","Twarda zasada: \u017Cadnych porad medycznych i \u017Cadnych danych o stanie zdrowia w wiadomo\u015Bciach. Pytania o objawy przekierowujemy do kontaktu telefonicznego lub wizyty. Komentarze z negatywn\u0105 opini\u0105 zostaj\u0105 widoczne, odpowied\u017A idzie publicznie i bez ujawniania, czy autor by\u0142 pacjentem, bo samo potwierdzenie tego faktu jest ujawnieniem danych o zdrowiu."]},{heading:"Kampanie Meta Ads dla plac\xF3wki",paragraphs:["Reklamy uruchamiamy pod konkretny cel: zape\u0142nienie grafiku nowej poradni, promocj\u0119 us\u0142ugi komercyjnej albo pozyskanie kontakt\xF3w na konsultacj\u0119. Kampania bez celu liczbowego ko\u0144czy si\u0119 raportem z zasi\u0119gami, kt\xF3rych nie da si\u0119 prze\u0142o\u017Cy\u0107 na przych\xF3d.","Meta ma osobne ograniczenia dla reklam dotycz\u0105cych zdrowia - nie pozwala mi\u0119dzy innymi kierowa\u0107 przekazu na domniemany stan zdrowia odbiorcy. Piszemy wi\u0119c teksty m\xF3wi\u0105ce o us\u0142udze i plac\xF3wce, nie o problemie odbiorcy, i to samo dotyczy kierowania kampanii.","Kampanie nie wchodz\u0105 w \u017Caden pakiet prowadzenia profili - wyceniamy je osobno, zale\u017Cnie od celu i liczby kampanii. Bud\u017Cet mediowy, czyli kwota wydana na same reklamy w Meta, jest osobnym kosztem."],bullets:["cel kampanii wyra\u017Cony liczb\u0105 kontakt\xF3w lub wizyt, nie zasi\u0119giem","osobne kampanie dla us\u0142ug komercyjnych i dla informacji organizacyjnych","pomiar telefon\xF3w i formularzy, nie tylko klikni\u0119\u0107","raport miesi\u0119czny z kosztem pozyskania kontaktu"]},{heading:"Jak wygl\u0105da wsp\xF3\u0142praca",paragraphs:["Zaczynamy od audytu profili i przegl\u0105du tego, co plac\xF3wka publikowa\u0142a do tej pory. Potem ustalamy plan tre\u015Bci na miesi\u0105c, zbieramy materia\u0142 zdj\u0119ciowy i wideo na miejscu albo pracujemy na materia\u0142ach plac\xF3wki, a publikacj\u0119 poprzedza akceptacja.","Pierwszy miesi\u0105c obejmuje audyt i optymalizacj\u0119 profili albo ich za\u0142o\u017Cenie, razem z wizyt\xF3wk\u0105 Google. Dalej zakres ustalamy pod plac\xF3wk\u0119: od samych post\xF3w graficznych i karuzel edukacyjnych, przez rolki na Instagram i Facebook, po filmy na TikToku i comiesi\u0119czn\u0105 sesj\u0119 nagraniowo-zdj\u0119ciow\u0105 na miejscu. Wycen\u0119 przygotowujemy po bezp\u0142atnej konsultacji, jako sta\u0142\u0105 miesi\u0119czn\u0105 kwot\u0119 za uzgodnion\u0105 liczb\u0119 publikacji."]}],faq:[{question:"Czy klinika mo\u017Ce pokazywa\u0107 pacjent\xF3w w social mediach?",answer:"Tylko za pisemn\u0105 zgod\u0105 na publikacj\u0119 wizerunku, ze wskazaniem kana\u0142u i mo\u017Cliwo\u015Bci\u0105 wycofania. Samo pokazanie osoby w plac\xF3wce medycznej ujawnia informacj\u0119 o korzystaniu ze \u015Bwiadcze\u0144, czyli dane szczeg\xF3lnej kategorii. Bez zgody publikujemy wy\u0142\u0105cznie materia\u0142y z zespo\u0142em i wn\u0119trzami bez pacjent\xF3w."},{question:"Czy prowadzicie social media dla pojedynczego lekarza, nie dla ca\u0142ej plac\xF3wki?",answer:"Tak. Profil lekarza prowadzimy jako mark\u0119 osobist\u0105: zakres przyj\u0119\u0107, prowadzone przypadki, sprz\u0119t, wyst\u0105pienia i publikacje. To inna praca ni\u017C profil przychodni, kt\xF3ra komunikuje g\u0142\xF3wnie dost\u0119pno\u015B\u0107 i organizacj\u0119. Przy lekarzu przyjmuj\u0105cym w kilku miejscach ustalamy na starcie, kt\xF3re tre\u015Bci nale\u017C\u0105 do jego marki, a kt\xF3re do marki plac\xF3wki."},{question:"Ile kosztuje prowadzenie social medi\xF3w dla lekarza lub kliniki?",answer:"Koszt zale\u017Cy od liczby kana\u0142\xF3w, liczby publikacji w miesi\u0105cu i tego, czy w zakresie s\u0105 rolki i sesje nagraniowe na miejscu. Wycen\u0119 podajemy po bezp\u0142atnej konsultacji jako sta\u0142\u0105 miesi\u0119czn\u0105 kwot\u0119. Kampanie Meta Ads i bud\u017Cet wydany na same reklamy to osobne pozycje."},{question:"Co lekarz mo\u017Ce publikowa\u0107 w social mediach?",answer:"Informacje o zakresie przyj\u0119\u0107, kwalifikacjach, miejscach pracy i przebiegu leczenia, materia\u0142y edukacyjne oraz relacje z konferencji. Kodeks Etyki Lekarskiej od 2025 roku pozwala informowa\u0107 o dzia\u0142alno\u015Bci zawodowej, ale nadal zakazuje przedstawiania si\u0119 jako najlepszy lub jedyny, deprecjonowania innych lekarzy i promowania produkt\xF3w niezwi\u0105zanych z medycyn\u0105."},{question:"Ile post\xF3w miesi\u0119cznie ma sens dla plac\xF3wki medycznej?",answer:"Cztery publikacje tygodniowo utrzymuj\u0105 profil w rotacji i daj\u0105 zapas tre\u015Bci na wiadomo\u015Bci i relacje. Poni\u017Cej dw\xF3ch tygodniowo profil wygl\u0105da na porzucony. Powy\u017Cej o\u015Bmiu ro\u015Bnie koszt, a przyrost kontakt\xF3w zwykle ju\u017C nie nad\u0105\u017Ca."},{question:"Kto odpowiada na wiadomo\u015Bci od pacjent\xF3w?",answer:"Ustalamy podzia\u0142 na starcie. Pytania organizacyjne - godziny, ceny, zakres us\u0142ug - obs\u0142ugujemy my. Wszystko, co dotyczy stanu zdrowia, terminu wizyty konkretnego pacjenta lub wynik\xF3w, idzie do rejestracji plac\xF3wki. Nigdy nie udzielamy porad medycznych w imieniu plac\xF3wki."},{question:"Czy prowadzicie profile na TikToku i YouTubie?",answer:"Prowadzimy, je\u015Bli plac\xF3wka ma specjalist\u0119 gotowego regularnie wyst\u0119powa\u0107 przed kamer\u0105. Bez tego kana\u0142y wideo nie maj\u0105 z czego \u017Cy\u0107 i lepiej zainwestowa\u0107 ten bud\u017Cet w Google i wizyt\xF3wk\u0119."}],related:[{path:"/wiedza/social-media-dla-lekarzy",label:"Social media dla lekarzy: co publikowa\u0107 i czego nie wolno",description:"Poradnik dla lekarzy i gabinet\xF3w prowadz\u0105cych profil samodzielnie."},{path:"/uslugi/wizytowka-google-dla-placowki",label:"Wizyt\xF3wka Google dla plac\xF3wki",description:"Pacjent sprawdza mapy i opinie, zanim otworzy Facebooka."},{path:"/wiedza/rodo-w-marketingu-placowki-medycznej",label:"RODO w marketingu plac\xF3wki medycznej",description:"Zgody na wizerunek, opinie i kontakt - co trzeba mie\u0107 na pi\u015Bmie."}]},{slug:"wizytowka-google-dla-placowki",navLabel:"Wizyt\xF3wka Google",h1:"Wizyt\xF3wka Google dla plac\xF3wki medycznej",seoTitle:"Prowadzenie i pozycjonowanie wizyt\xF3wki Google dla plac\xF3wek medycznych | mediaso",seoDescription:"Prowadzimy i pozycjonujemy wizyt\xF3wki Google klinik, przychodni i gabinet\xF3w: kategorie, us\u0142ugi, zdj\u0119cia, opinie pacjent\xF3w, posty i raport widoczno\u015Bci w mapach.",schemaName:"Optymalizacja Profilu Firmy w Google",schemaServiceType:"Local SEO",lead:"Wizyt\xF3wka Google jest dla plac\xF3wki medycznej wa\u017Cniejsza ni\u017C strona internetowa, bo pacjent widzi j\u0105 pierwsz\u0105 i cz\u0119sto na niej ko\u0144czy. Z panelu w mapach dzwoni, sprawdza godziny, czyta opinie i wyznacza tras\u0119 - bez otwierania witryny. Trzy rzeczy decyduj\u0105 o tym, czy plac\xF3wka pojawia si\u0119 w lokalnych wynikach: poprawnie dobrana kategoria g\u0142\xF3wna, kompletno\u015B\u0107 profilu oraz opinie, ich liczba, \u015Bwie\u017Co\u015B\u0107 i odpowiedzi plac\xF3wki. Wi\u0119kszo\u015B\u0107 wizyt\xF3wek przychodni przegrywa na pierwszym punkcie, bo ma ustawion\u0105 kategori\u0119 og\xF3ln\u0105 zamiast tej, kt\xF3rej realnie szuka pacjent. Prowadzimy profil jak sta\u0142\u0105 pozycj\u0119: uzupe\u0142niamy us\u0142ugi i godziny, publikujemy zdj\u0119cia i posty, pilnujemy sp\xF3jno\u015Bci danych z innymi serwisami i odpowiadamy na opinie w spos\xF3b, kt\xF3ry nie ujawnia, kto by\u0142 pacjentem.",sections:[{heading:"Kategoria i us\u0142ugi - miejsce, gdzie przegrywa wi\u0119kszo\u015B\u0107 plac\xF3wek",paragraphs:['Kategoria g\u0142\xF3wna to najmocniejszy sygna\u0142 w lokalnych wynikach. Przychodnia z kategori\u0105 \u201Eprzychodnia" nie pojawi si\u0119 na zapytanie o ortodont\u0119, nawet je\u015Bli ortodonta przyjmuje na miejscu. Dobieramy kategori\u0119 g\u0142\xF3wn\u0105 pod us\u0142ug\u0119 o najwi\u0119kszej warto\u015Bci i uzupe\u0142niamy list\u0119 kategorii dodatkowych.',"Do tego wype\u0142niamy sekcj\u0119 us\u0142ug konkretnymi nazwami zabieg\xF3w i bada\u0144 z kr\xF3tkimi opisami. Ta lista pojawia si\u0119 w profilu i pomaga Google zrozumie\u0107, na jakie zapytania wy\u015Bwietla\u0107 plac\xF3wk\u0119."],bullets:["dob\xF3r kategorii g\u0142\xF3wnej pod us\u0142ug\u0119 o najwy\u017Cszej warto\u015Bci","kategorie dodatkowe pokrywaj\u0105ce reszt\u0119 zakresu przyj\u0119\u0107","lista us\u0142ug z opisami i cenami, je\u015Bli plac\xF3wka je publikuje","atrybuty: dost\u0119pno\u015B\u0107 dla w\xF3zk\xF3w, parking, p\u0142atno\u015Bci, teleporady"]},{heading:"Godziny, zdj\u0119cia i posty",paragraphs:["Godziny musz\u0105 by\u0107 zgodne z rzeczywisto\u015Bci\u0105, \u0142\u0105cznie z dniami \u015Bwi\u0105tecznymi i przerwami urlopowymi. Pacjent, kt\xF3ry przyjdzie pod zamkni\u0119te drzwi w godzinach podanych w mapach, zostawia opini\u0119 i to ta opinia zostaje na lata.","Zdj\u0119cia aktualizujemy cyklicznie: wej\u015Bcie od strony ulicy, poczekalnia, gabinety, zesp\xF3\u0142, sprz\u0119t. Wej\u015Bcie od ulicy jest wa\u017Cniejsze, ni\u017C si\u0119 wydaje - po nim pacjent rozpoznaje budynek. Posty publikujemy z informacjami o wolnych terminach, nowych specjalistach i zmianach organizacyjnych."]},{heading:"Opinie: zbieranie i odpowiadanie",paragraphs:["Pro\u015Bb\u0119 o opini\u0119 wysy\u0142amy do wszystkich pacjent\xF3w z danej grupy, nie tylko do tych, kt\xF3rzy wygl\u0105daj\u0105 na zadowolonych, i nie oferujemy niczego w zamian. Selekcja i wynagradzanie \u0142ami\u0105 zasady Google i wywracaj\u0105 wiarygodno\u015B\u0107 profilu, gdy wyjd\u0105 na jaw.","Odpowiadamy na ka\u017Cd\u0105 opini\u0119, tak\u017Ce negatywn\u0105, i nigdy nie potwierdzamy w odpowiedzi, \u017Ce autor by\u0142 pacjentem plac\xF3wki. Standardowa formu\u0142a: podzi\u0119kowanie, zaproszenie do kontaktu bezpo\u015Bredniego, \u017Cadnych szczeg\xF3\u0142\xF3w o leczeniu. Wyja\u015Bnienia id\u0105 w rozmowie, nie publicznie."],bullets:["pro\u015Bba o opini\u0119 po wizycie, wysy\u0142ana systemowo do ca\u0142ej grupy pacjent\xF3w","odpowied\u017A na ka\u017Cd\u0105 opini\u0119 w ci\u0105gu kilku dni roboczych","zg\u0142aszanie opinii \u0142ami\u0105cych zasady platformy zamiast wdawania si\u0119 w sp\xF3r","monitoring \u015Bredniej oceny i tempa przyrostu opinii"]},{heading:"Plac\xF3wki z kilkoma adresami",paragraphs:["Ka\u017Cdy oddzia\u0142 to osobna wizyt\xF3wka pod w\u0142asnym adresem i numerem telefonu, spi\u0119ta z podstron\u0105 tego oddzia\u0142u na stronie. Wsp\xF3lna wizyt\xF3wka dla trzech lokalizacji nie wy\u015Bwietli si\u0119 w \u017Cadnej z nich poprawnie.","Przy wi\u0119kszej liczbie oddzia\u0142\xF3w pilnujemy sp\xF3jno\u015Bci nazw i danych mi\u0119dzy wizyt\xF3wkami, katalogami bran\u017Cowymi i stron\u0105. Rozjazd w numerze telefonu albo w nazwie os\u0142abia lokalne wyniki wszystkich lokalizacji naraz."]}],faq:[{question:"Czy plac\xF3wka medyczna mo\u017Ce mie\u0107 wizyt\xF3wk\u0119 Google bez podawania adresu?",answer:"Plac\xF3wka przyjmuj\u0105ca pacjent\xF3w w gabinecie musi poda\u0107 adres - to warunek pojawienia si\u0119 w mapach. Ukrycie adresu jest przewidziane dla firm doje\u017Cd\u017Caj\u0105cych do klienta i przy stacjonarnej przychodni zadzia\u0142a przeciwko widoczno\u015Bci."},{question:"Jak szybko wida\u0107 efekty optymalizacji wizyt\xF3wki?",answer:"Zmiany kategorii i uzupe\u0142nienie profilu Google przetwarza zwykle w kilka dni, a pierwsze r\xF3\u017Cnice w liczbie wy\u015Bwietle\u0144 i telefon\xF3w wida\u0107 w statystykach profilu po dw\xF3ch do czterech tygodniach. Wzrost nap\u0119dzany opiniami jest wolniejszy, bo zale\u017Cy od tempa ich zbierania."},{question:"Co zrobi\u0107 z fa\u0142szyw\u0105 negatywn\u0105 opini\u0105?",answer:"Zg\u0142osi\u0107 j\u0105 do Google jako naruszenie zasad i r\xF3wnolegle odpowiedzie\u0107 publicznie w spos\xF3b rzeczowy, bez ujawniania, czy autor by\u0142 pacjentem. Google usuwa cz\u0119\u015B\u0107 zg\u0142osze\u0144, ale nie wszystkie - spokojna odpowied\u017A pod opini\u0105 pracuje na wizerunek nawet wtedy, gdy opinia zostaje."},{question:"Ile kosztuje prowadzenie wizyt\xF3wki Google dla przychodni?",answer:"Zale\u017Cy od liczby lokalizacji i zakresu: samo wdro\u017Cenie profilu to jednorazowa praca, sta\u0142e prowadzenie z postami, zdj\u0119ciami, odpowiedziami na opinie i raportem to miesi\u0119czny abonament. Wycen\u0119 podajemy po bezp\u0142atnym przegl\u0105dzie wizyt\xF3wki, jako sta\u0142\u0105 kwot\u0119 za uzgodniony zakres."},{question:"Czy warto p\u0142aci\u0107 za pozycjonowanie wizyt\xF3wki?",answer:"Warto, je\u015Bli praca polega na uzupe\u0142nianiu profilu, zbieraniu opinii i publikowaniu tre\u015Bci. Nie warto, je\u015Bli wykonawca obiecuje sztuczne opinie albo manipulacj\u0119 lokalizacj\u0105 - Google karze za to zawieszeniem profilu, a odzyskanie go bywa trudne."}],related:[{path:"/uslugi/pozycjonowanie-klinik",label:"Pozycjonowanie klinik",description:"Wizyt\xF3wka i strona pracuj\u0105 razem albo \u017Cadna nie wychodzi wysoko."},{path:"/uslugi/social-media-dla-klinik",label:"Social media dla klinik",description:"Drugie miejsce, w kt\xF3rym pacjent sprawdza plac\xF3wk\u0119 przed telefonem."},{path:"/wiedza/jak-zbierac-opinie-pacjentow",label:"Jak zbiera\u0107 opinie pacjent\xF3w zgodnie z prawem",description:"Gotowa procedura zbierania opinii bez selekcji i nagr\xF3d."}]}];var z="/uslugi",n="/wiedza",r=a=>`${z}/${a}`,t=a=>`${n}/${a}`,d=a=>o.find(e=>e.slug===a),p=a=>i.find(e=>e.slug===a),k=["/","/uslugi","/o-nas","/kontakt","/diagnostyka",n,...o.map(a=>r(a.slug)),...i.map(a=>t(a.slug))];export{i as a,o as b,r as c,t as d,d as e,p as f};
